    /// <summary>Flush the owner's file buffers through the operating system to storage.</summary>
    public static int fsync(int descriptor)
    {
        var slot = SlotByFd(descriptor);
        if (slot is null) { errno = EBADF; return -1; }
        if (slot.Stream is BackendDirectoryStream directory) return BackendDirectoryFsync(directory);
        if (slot.Stream is not FileStream file) { errno = EINVAL; return -1; }
        try { slot.Writer?.Flush(); file.Flush(flushToDisk: true); return 0; }
        catch (ObjectDisposedException) { errno = EBADF; return -1; }
        catch (UnauthorizedAccessException) { errno = EACCES; return -1; }
        catch (IOException) { errno = EIO; return -1; }
    }

    public static int truncate(byte* path, long length)
    {
        if (path == null) { errno = EFAULT; return -1; }
        if (length < 0) { errno = EINVAL; return -1; }
        var descriptor = open(path, 1);
        if (descriptor < 0) return -1;
        var result = ftruncate(descriptor, length);
        var error = errno;
        close(descriptor);
        if (result != 0) errno = error;
        return result;
    }

    public static int fchmod(int descriptor, uint mode)
    {
        var slot = SlotByFd(descriptor);
        if (slot is null) { errno = EBADF; return -1; }
        if (OperatingSystem.IsWindows()) { errno = ENOTSUP; return -1; }
        if (slot.Stream is not FileStream file) { errno = EINVAL; return -1; }
        try { File.SetUnixFileMode(file.SafeFileHandle, (UnixFileMode)(mode & 0xfff)); return 0; }
        catch (ObjectDisposedException) { errno = EBADF; return -1; }
        catch (UnauthorizedAccessException) { errno = EPERM; return -1; }
        catch (IOException) { errno = EIO; return -1; }
    }

    /// <summary>Atomically create a private file, replacing the template's final six X bytes.</summary>
    public static int mkstemp(byte* template)
    {
        if (template == null) { errno = EFAULT; return -1; }
        var length = strlen(template);
        if (length < 6) { errno = EINVAL; return -1; }
        for (var i = length - 6; i < length; i++)
            if (template[i] != (byte)'X') { errno = EINVAL; return -1; }
        var prefix = Encoding.UTF8.GetString(template, length - 6);
        const string alphabet = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
        Span<char> suffix = stackalloc char[6];
        for (var attempt = 0; attempt < 128; attempt++)
        {
            for (var i = 0; i < suffix.Length; i++) suffix[i] = alphabet[global::System.Security.Cryptography.RandomNumberGenerator.GetInt32(alphabet.Length)];
            var path = ResolvePath(prefix + new string(suffix));
            if (OperatingSystem.IsLinux() && RuntimeInformation.ProcessArchitecture == Architecture.X64)
            {
                var descriptor = OpenLinuxFile(path, 2 | 0x40 | 0x80, 0x180); // O_RDWR|O_CREAT|O_EXCL, 0600
                if (descriptor < 0)
                {
                    if (errno == EEXIST) continue;
                    return -1;
                }
                for (var i = 0; i < suffix.Length; i++) template[length - 6 + i] = (byte)suffix[i];
                return descriptor;
            }
            FileStream? file = null;
            try
            {
                var options = new FileStreamOptions { Mode = FileMode.CreateNew, Access = FileAccess.ReadWrite,
                    Share = FileShare.ReadWrite | FileShare.Delete };
                if (!OperatingSystem.IsWindows()) options.UnixCreateMode = UnixFileMode.UserRead | UnixFileMode.UserWrite;
                file = new FileStream(path, options);
                var descriptor = RegisterFileSlot(file);
                file = null; // Ownership transferred to the descriptor table.
                for (var i = 0; i < suffix.Length; i++) template[length - 6 + i] = (byte)suffix[i];
                return descriptor;
            }
            catch (IOException) when (File.Exists(path) || Directory.Exists(path)) { }
            catch (DirectoryNotFoundException) { errno = ENOENT; return -1; }
            catch (UnauthorizedAccessException) { errno = EACCES; return -1; }
            catch (ArgumentException) { errno = EINVAL; return -1; }
            catch (IOException) { errno = EIO; return -1; }
            finally { file?.Dispose(); }
        }
        errno = EEXIST;
        return -1;
    }
}


#nullable restore
// ---- FileLib.cs ----
#nullable enable



/// <summary>
/// C <c>&lt;stdio.h&gt;</c> file I/O: the <c>FILE*</c> stream surface
/// (<c>fopen</c> / <c>fclose</c> / <c>freopen</c> / <c>fread</c> / <c>fwrite</c> /
/// <c>fseek</c> / <c>ftell</c> / <c>rewind</c> / <c>feof</c> / <c>ferror</c> /
/// <c>clearerr</c> / <c>fflush</c> + <c>remove</c> / <c>rename</c> /
/// <c>tmpfile</c>), plus the three standard streams.
/// </summary>
/// <remarks>
/// <para>
/// <b>FILE model.</b> C code always uses <c>FILE *</c>, never <c>FILE</c> by
/// value, so dotcc keeps <c>FILE</c> a tiny opaque struct (one <c>int</c> slot)
/// and lets <c>FILE*</c> stay a genuine pointer — <c>NULL</c>, <c>==</c>, and
/// <c>if (fp)</c> all work through the normal pointer machinery, no emitter
/// special-casing. The slot indexes <see cref="_files"/>, a managed table that
/// holds the real backing (<see cref="FileSlot"/>).
/// </para>
/// <para>
/// <b>Two backings.</b> Slots 0/1/2 are <c>stdin</c>/<c>stdout</c>/<c>stderr</c>
/// and route text through <see cref="Console.In"/> / <see cref="Console.Out"/> /
/// <see cref="Console.Error"/>, <i>resolved per call</i> so <c>Console.SetIn</c> /
/// <c>SetOut</c> redirection (and the functional harness's stdout capture) is
/// honored — never the raw OS handle. <c>fopen</c>'d slots wrap a
/// <see cref="FileStream"/> (binary, seekable). <c>freopen</c> swaps a slot's
/// backing while keeping the same <c>FILE*</c> identity — the standard way to
/// point <c>stdin</c>/<c>stdout</c> at a file (C99 7.19.5.4).
/// </para>
/// <para>
/// <b>Seekability.</b> <c>fseek</c>/<c>ftell</c> on a console stream return the
/// error result and set <c>errno</c> — terminals/pipes aren't seekable, which
/// is conformant. Only file-backed handles seek.
/// </para>
/// </remarks>
public static unsafe partial class Libc
{
    /// <summary>
    /// Opaque stdio handle. Holds only a slot index into <see cref="_files"/>,
    /// so a <c>FILE*</c> is a plain pointer-to-struct. Seeded as a known type
    /// name in <c>Compiler.PredefinedTypeNames</c> so user C can spell
    /// <c>FILE *fp</c> with no typedef.
    /// </summary>
    public struct FILE { public int _slot; }

    /// <summary>Managed backing for one open <see cref="FILE"/>.</summary>
    private sealed class FileSlot
    {
        public enum K { In, Out, Err, File, Socket, Pipe, Directory }
        public K Kind;
        public Stream? Stream;          // null for the console + socket kinds
        public ManagedPipe? Pipe;
        public Socket? Socket;          // socket kind only (BSD sockets, SocketLib)
        private int statusFlags;
        public SharedFileDescription? Description;
        public int StatusFlags
        {
            get => Description?.StatusFlags ?? statusFlags;
            set { if (Description is { } shared) shared.StatusFlags = value; else statusFlags = value; }
        }
        public int DescriptorFlags;     // FD_CLOEXEC (dotcc has no managed exec)
        public bool Listening;
        public bool Connecting;
        public int PendingSocketError;  // poll preserves SO_ERROR until read
        public StreamFileWriter? Writer; // lazy, file kind only
        public StreamFileReader? Reader; // lazy, file kind only
        public bool Eof;
        public bool Err;
        public int Pushback = -1;       // one byte pushed back by ungetc (-1 = none)
        public int PendingWide = -1;    // one wchar_t pending for the wide reader
                                        // (a stashed low surrogate, or an ungetwc
                                        // pushback); -1 = none. See ReadWideFrom.
        public int BufferMode = -1;    // -1 preserves legacy backing behavior
        public byte* UserBuffer;       // borrowed until fclose/setvbuf
        public byte[]? OutputBuffer;   // used only when caller requested allocation
        public int BufferCapacity, BufferedBytes;
        public int StdioAccess;        // 0=legacy, 1=read, 2=write, 3=read/write
        public Decoder? ConsoleDecoder; // preserves UTF-8 across buffered byte writes
    }

    // Runtime-bound descriptors are isolated; unbound calls use the legacy context.
    private static List<FileSlot?> _files => FileDescriptors.Files;
    private static Lock _filesLock => FileDescriptors.Sync;
    private static ref FILE* _stdinP => ref FileDescriptors.Stdin;
    private static ref FILE* _stdoutP => ref FileDescriptors.Stdout;
    private static ref FILE* _stderrP => ref FileDescriptors.Stderr;

    // Thread-safe lazy init for the std-stream FILE*s: build under _filesLock
    // and publish only the finished pointer, so concurrent first-callers (e.g.
    // parallel test collections, or a multithreaded emitted program) hand out
    // ONE stable FILE* per std stream rather than racing to allocate two.
    private static FILE* StdStream(ref FILE* slotField, int slot)
    {
        var existing = slotField;
        if (existing != null) { return existing; }
        lock (_filesLock)
        {
            if (slotField != null) { return slotField; }
            var p = AllocateFileHandle(slot);
            slotField = p;       // publish only after _slot is set
            return p;
        }
    }

    /// <summary>Standard input stream (<c>FILE*</c>). Routes through <see cref="Console.In"/>.</summary>
    public static FILE* stdin => StdStream(ref _stdinP, 0);

    /// <summary>Standard output stream (<c>FILE*</c>). Routes through <see cref="Console.Out"/>.</summary>
    public static FILE* stdout => StdStream(ref _stdoutP, 1);

    /// <summary>Standard error stream (<c>FILE*</c>). Routes through <see cref="Console.Error"/>.</summary>
    public static FILE* stderr => StdStream(ref _stderrP, 2);

    private static FileSlot? Slot(FILE* f)
    {
        if (f == null) { return null; }
        var state = FileDescriptors;
        lock (state.Sync)
        {
            // Check ownership before dereferencing a foreign or retired FILE*.
            if (!state.Handles.Contains((nint)f)) { errno = EBADF; return null; }
            var i = f->_slot;
            return (uint)i < (uint)state.Files.Count ? state.Files[i] : null;
        }
    }

    // ---- text accessors used by fprintf / fscanf (PrintfBuilder/ScanfReader
    //      bind a TextWriter/TextReader; FILE just supplies the right one) ----

    // Pattern-match the slot directly (not `s?.Kind`): the `Stream: { } st`
    // sub-pattern binds the non-null backing stream and `s` binds the matched
    // (non-null) slot, so neither needs a null-forgiving `!`.
    internal static TextWriter WriterFor(FILE* f) => Slot(f) switch
    {
        { BufferMode: >= 0 } s => s.Writer ??= new StreamFileWriter(s),
        { Kind: FileSlot.K.Out } => Console.Out,
        { Kind: FileSlot.K.Err } => Console.Error,
        { Kind: FileSlot.K.File, Stream: { } } s => s.Writer ??= new StreamFileWriter(s),
        _ => TextWriter.Null, // not an output stream — drop, don't throw
    };

    internal static TextReader ReaderFor(FILE* f) => Slot(f) switch
    {
        { Kind: FileSlot.K.In } => Console.In,
        { Kind: FileSlot.K.File, Stream: { } st } s => s.Reader ??= new StreamFileReader(st),
        _ => TextReader.Null,
    };

    // ---- byte helpers used by fputc/fputs/fgetc/fgets ----
    //
    // For files these hit the FileStream byte-exact (fputc/fgetc are
    // byte-oriented in C); for the console they go through Console.* as chars,
    // which is exactly correct for ASCII (matches dotcc's UTF-8-in-char* model).

    internal static bool WriteByteTo(FILE* f, byte b)
    {
        if (Slot(f) is { } s) return WriteByteSlot(s, b);
        errno = EBADF;
        return false;
    }

    private static bool WriteByteSlot(FileSlot s, byte b)
    {
        if (s.StdioAccess == 1 || s.Stream is { CanWrite: false }) { errno = EBADF; s.Err = true; return false; }
        try
        {
            if (s.BufferMode is 0 or 1)
            {
                if (s.UserBuffer != null) s.UserBuffer[s.BufferedBytes] = b;
                else s.OutputBuffer![s.BufferedBytes] = b;
                s.BufferedBytes++;
                return s.BufferedBytes < s.BufferCapacity && !(s.BufferMode == 1 && b == (byte)'\n')
                    || FlushStdioBuffer(s);
            }
            var result = WriteByteBacking(s, b);
            if (result && s.BufferMode == 2) FlushBacking(s);
            return result;
        }
        catch (IOException) { errno = FileIoError(s); s.Err = true; return false; }
        catch (ObjectDisposedException) { errno = EBADF; s.Err = true; return false; }
    }

    private static bool WriteByteBacking(FileSlot s, byte b)
    {
        // Socket-backed fd: one byte onto the connection (fputc on an fdopen'd socket).
        if (s.Kind == FileSlot.K.Pipe) { var ok = PipeWrite(s, &b, 1) == 1; if (!ok) s.Err = true; return ok; }
        if (s.Kind == FileSlot.K.Socket) { return SocketWriteByte(s, b); }
        // Only file-backed slots carry a Stream; the console kinds have none.
        if (s.Stream is { } st)
        {
            // A read-only stream (file opened "r") can't be written — C's fputc/
            // fwrite return EOF / a short count and set the error indicator rather
            // than faulting. Mirror that instead of letting Stream.WriteByte throw.
            if (!st.CanWrite) { errno = EBADF; s.Err = true; return false; }
            if ((s.StatusFlags & 0x400) != 0 && st.CanSeek) st.Seek(0, SeekOrigin.End);
            st.WriteByte(b);
            return true;
        }
        if (s.Kind == FileSlot.K.In) { errno = EBADF; s.Err = true; return false; }
        var console = s.Kind == FileSlot.K.Err ? Console.Error : Console.Out;
        if (s.BufferMode >= 0)
        {
            Span<byte> input = stackalloc byte[1] { b };
            Span<char> output = stackalloc char[2];
            s.ConsoleDecoder ??= Encoding.UTF8.GetDecoder();
            var count = s.ConsoleDecoder.GetChars(input, output, flush: false);
            console.Write(output[..count]);
        }
        else console.Write((char)b);
        return true;
    }

    internal static int ReadByteFrom(FILE* f)
    {
        if (Slot(f) is { } s) return ReadByteSlot(s);
        errno = EBADF;
        return -1;
    }

    private static int ReadByteSlot(FileSlot s, bool stdio = true)
    {
        if (stdio && s.StdioAccess == 2) { errno = EBADF; s.Err = true; return -1; }
        if (s.Kind == FileSlot.K.Directory) { errno = EISDIR; s.Err = true; return -1; }
        // A byte pushed back by ungetc is returned before touching the stream
        // (covers fgetc / getc / getchar / fgets — the common ungetc consumers).
        if (s.Pushback >= 0) { var p = s.Pushback; s.Pushback = -1; return p; }
        // Socket-backed fd: one byte off the connection (fgetc on an fdopen'd socket).
        if (s.Kind == FileSlot.K.Pipe)
        {
            byte value;
            var count = PipeRead(s, &value, 1);
            if (count == 0) s.Eof = true;
            if (count < 0) s.Err = true;
            return count == 1 ? value : -1;
        }
        if (s.Kind == FileSlot.K.Socket) { return SocketReadByte(s); }
        int r;
        if (s.Stream is { } st)
        {
            // A write-only stream (file opened "w"/"a") can't be read. C's fgetc
            // returns EOF there but sets the ERROR indicator (not the EOF one), so
            // file:read reports (nil, msg, errno) rather than a plain-EOF nil.
            if (!st.CanRead) { errno = EBADF; s.Err = true; return -1; }
            r = (s.Reader ??= new StreamFileReader(st)).Read(); // shares the scanf pushback
        }
        else
        {
            r = Console.In.Read();
        }
        if (r < 0) { s.Eof = true; return -1; }
        return r & 0xFF;
    }

    /// <summary>Read one <c>wchar_t</c> (a UTF-16 code unit) from <paramref name="f"/>,
    /// decoding dotcc's narrow encoding (UTF-8) off the byte reader — the wide
    /// counterpart of <see cref="ReadByteFrom"/>, byte-stream-consistent (it shares
    /// the same underlying bytes and the <c>ungetc</c> pushback). A code point above
    /// U+FFFF yields a UTF-16 surrogate pair: the high half is returned now and the
    /// low half stashed in the slot for the next call. A malformed sequence yields
    /// U+FFFD. Returns -1 (<c>WEOF</c>) at end of input. Also honors a wide pushback
    /// set by <see cref="UngetWideTo"/>.</summary>
    internal static int ReadWideFrom(FILE* f)
    {
        if (Slot(f) is not { } s) { return -1; }
        if (s.PendingWide >= 0) { var p = s.PendingWide; s.PendingWide = -1; return p; }
        var b0 = ReadByteSlot(s);
        if (b0 < 0) { return -1; }
        if (b0 < 0x80) { return b0; }
        int n, cp;
        if ((b0 & 0xE0) == 0xC0) { n = 1; cp = b0 & 0x1F; }
        else if ((b0 & 0xF0) == 0xE0) { n = 2; cp = b0 & 0x0F; }
        else if ((b0 & 0xF8) == 0xF0) { n = 3; cp = b0 & 0x07; }
        else { return 0xFFFD; }                       // stray continuation / invalid lead
        for (var i = 0; i < n; i++)
        {
            var b = ReadByteSlot(s);
            if (b < 0 || (b & 0xC0) != 0x80) { return 0xFFFD; }   // truncated / invalid
            cp = (cp << 6) | (b & 0x3F);
        }
        if (cp > 0xFFFF)
        {
            cp -= 0x10000;
            s.PendingWide = 0xDC00 + (cp & 0x3FF);    // low surrogate returned next call
            return 0xD800 + (cp >> 10);               // high surrogate now
        }
        return cp;
    }

    /// <summary>Push one <c>wchar_t</c> back so the next <see cref="ReadWideFrom"/>
    /// returns it (the wide <c>ungetc</c>). Only one is held; pushing <c>WEOF</c> or
    /// when one is already pending fails. Clears the slot's EOF flag.</summary>
    internal static int UngetWideTo(FILE* f, int c)
    {
        if (c < 0 || Slot(f) is not { } s || s.PendingWide >= 0) { return -1; }
        s.PendingWide = c & 0xFFFF;
        s.Eof = false;
        return c & 0xFFFF;
    }

    // ---------------------------------------------------------------------
    // fopen / freopen / fclose
    // ---------------------------------------------------------------------

    /// <summary>
    /// <c>fopen(path, mode)</c> — open <paramref name="path"/> per the C mode
    /// string (<c>r</c>/<c>w</c>/<c>a</c>, optional <c>+</c> for read-write,
    /// optional <c>b</c> ignored — .NET streams are binary). Returns a
    /// <c>FILE*</c> or <c>null</c> (with <c>errno</c> set) on failure.
    /// </summary>
    public static FILE* fopen(byte* path, byte* mode)
    {
        if (path == null || mode == null) { errno = EINVAL; return null; }
        var p = ResolvePath(path);
        if (!ParseMode(mode, out var fileMode, out var access)) { errno = EINVAL; return null; }
        Stream stream;
        // The well-known Unix device files, backed by synthetic streams so C code
        // that uses them works on every host (on Windows the paths don't exist;
        // even on Unix, /dev/full's "writes accepted, flush fails" needs the C
        // stdio buffering dotcc doesn't have). /dev/null discards writes and reads
        // EOF; /dev/full accepts writes but fails to flush (ENOSPC).
        if (p == "/dev/null") { stream = Stream.Null; }
        else if (p == "/dev/full") { stream = new FullDeviceStream(); }
        else
        {
            var opened = OpenStdioFile(p, mode, fileMode, access);
            if (opened is null) return null;
            stream = opened;
        }
        var descriptor = -1;
        try
        {
            descriptor = RegisterFileSlot(stream);
            ConfigureStdioSlot(SlotByFd(descriptor)!, mode, access);
            return AllocateFileHandle(descriptor);
        }
        catch (OutOfMemoryException)
        {
            if (descriptor >= 0) close(descriptor); else stream.Dispose();
            errno = ENOMEM;
            return null;
        }
    }

    /// <summary>Adopt a descriptor in the same owner table, without opening,
    /// duplicating or truncating it. Failure never closes the descriptor.</summary>
    public static FILE* fdopen(int descriptor, byte* mode)
    {
        if (mode == null || !ParseMode(mode, out _, out var access)) { errno = EINVAL; return null; }
        var slot = SlotByFd(descriptor);
        if (slot is null) { errno = EBADF; return null; }
        var requested = access == FileAccess.Read ? 1 : access == FileAccess.Write ? 2 : 3;
        var actual = (slot.StatusFlags & 3) == 0 ? 1 : (slot.StatusFlags & 3) == 1 ? 2 : 3;
        if ((requested & actual) != requested) { errno = EINVAL; return null; }
        FILE* handle;
        try { handle = AllocateFileHandle(descriptor); }
        catch (OutOfMemoryException) { errno = ENOMEM; return null; }
        slot.StdioAccess = requested;
        if (*mode == (byte)'a') slot.StatusFlags |= 0x400;
        return handle;
    }

    /// <summary>
    /// <c>freopen(path, mode, stream)</c> — reassociate the existing
    /// <paramref name="stream"/> handle with <paramref name="path"/>, keeping
    /// the same <c>FILE*</c> (C99 7.19.5.4; the canonical way to redirect
    /// <c>stdin</c>/<c>stdout</c> to a file). Returns <paramref name="stream"/>
    /// on success, or <c>null</c> (closing the stream) on failure.
    /// </summary>
    public static FILE* freopen(byte* path, byte* mode, FILE* stream)
    {
        var slot = Slot(stream);
        if (slot == null || mode == null) { errno = EINVAL; return null; }
        // path == NULL: C says change mode of the existing stream — we have no
        // mode state to change, so just return the stream unchanged.
        if (path == null) { return stream; }
        // Drain the old stdio buffer BEFORE opening (and possibly truncating)
        // the replacement path. Byte-only output need not have a Writer.
        // Like native freopen, a failure flushing the old association does
        // not prevent opening the replacement; its indicators are reset below.
        try { FlushStdioBuffer(slot); slot.Writer?.Flush(); }
        catch (IOException) { }
        catch (ObjectDisposedException) { }
        try { ReleaseFileBacking(slot); }
        catch (IOException) { }
        catch (ObjectDisposedException) { }
        slot.Stream = null;
        slot.Writer = null;
        slot.Reader = null;
        // Even an invalid replacement mode closes the old association.
        if (!ParseMode(mode, out var fileMode, out var access)) { errno = EINVAL; CloseSlot(slot); return null; }
        var newStream = OpenStdioFile(ResolvePath(path), mode, fileMode, access);
        if (newStream is null)
        {
            var error = errno;
            CloseSlot(slot);
            errno = error;
            return null;
        }
        // Adopt in place, retaining FILE identity and caller-owned buffering.
        slot.Kind = newStream is BackendDirectoryStream ? FileSlot.K.Directory : FileSlot.K.File;
        slot.Stream = newStream;
        ConfigureStdioSlot(slot, mode, access);
        slot.Pushback = slot.PendingWide = -1;
        slot.ConsoleDecoder = null;
        slot.Eof = false;
        slot.Err = false;
        return stream;
    }

    /// <summary>
    /// <c>fclose(stream)</c> — flush and close a <c>fopen</c>'d stream. Returns
    /// 0 on success, <c>EOF</c> on error. Closing a std stream flushes it but
    /// leaves the slot usable.
    /// </summary>
    public static int fclose(FILE* stream)
    {
        var slot = Slot(stream);
        if (slot == null) { errno = EBADF; return -1; }
        // Invalidate the slot index BEFORE freeing, so a double-fclose on the
        // same FILE* won't read freed memory and corrupt a different file's slot.
        stream->_slot = -1;
        var result = 0;
        try { if (!FlushStdioBuffer(slot)) result = -1; }
        catch (IOException) { errno = FileIoError(slot); result = -1; }
        try { CloseSlot(slot); }
        catch (IOException) { errno = FileIoError(slot); result = -1; }
        // Free the native FILE struct (but never the cached std-stream structs).
        if (stream != _stdinP && stream != _stdoutP && stream != _stderrP)
        {
            lock (_filesLock) FileDescriptors.Handles.Remove((nint)stream);
            NativeMemory.Free(stream);
        }
        return result;
    }

    /// <summary>
    /// POSIX <c>fileno(stream)</c> — the fd behind a stream. dotcc's slot
    /// indices ARE its fds (0/1/2 = std streams, fopen'd slots follow), so
    /// this is just the stored index. -1 for NULL / a closed stream.
    /// </summary>
    public static int fileno(FILE* stream) => Slot(stream) == null ? -1 : stream->_slot;

    /// <summary>
    /// POSIX <c>close(fd)</c> — close by fd. The slot-level half of
    /// <see cref="fclose"/> (no <c>FILE*</c> to free — a caller holding one,
    /// chibi's fd-port finalizer, frees it via <c>fclose</c> separately).
    /// Closing 0/1/2 flushes and keeps the std stream usable, like fclose.
    /// </summary>
    public static int close(int fd)
    {
        var slot = SlotByFd(fd);
        if (slot == null) { errno = EBADF; return -1; }
        CloseSlot(slot);
        return 0;
    }

    /// <summary>POSIX <c>read(fd, buf, count)</c> — byte-level fd read over the
    /// slot's backing (file stream, or Console.In for fd 0).</summary>
    public static long read(int fd, void* buf, ulong count)
    {
        var s = SlotByFd(fd);
        if (s == null) { errno = EBADF; return -1; }
        if (s.Kind == FileSlot.K.Directory) { errno = EISDIR; return -1; }
        // A socket fd must return whatever is available NOW (up to count), not block
        // for the full count like the file byte-loop below would — one Receive.
        if (s.Kind == FileSlot.K.Pipe) return PipeRead(s, buf, count);
        if (s.Kind == FileSlot.K.Socket) { return SocketRecvInto(s, buf, count, 0); }
        var dst = (byte*)buf;
        long got = 0;
        for (; (ulong)got < count; got++)
        {
            var b = ReadByteSlot(s, stdio: false);
            if (b < 0) { break; }
            dst[got] = (byte)b;
        }
        return got;
    }

    /// <summary>POSIX <c>write(fd, buf, count)</c> — byte-level fd write over the
    /// slot's backing (file stream, or Console.Out/.Error for fds 1/2).</summary>
    public static long write(int fd, void* buf, ulong count)
    {
        var s = SlotByFd(fd);
        if (s == null) { errno = EBADF; return -1; }
        if (s.Kind == FileSlot.K.Directory) { errno = EBADF; return -1; }
        // Socket fd: one Send of the whole buffer (the byte-loop below is for the
        // file/console kinds whose backing has no bulk write).
        if (s.Kind == FileSlot.K.Pipe) return PipeWrite(s, buf, count);
        if (s.Kind == FileSlot.K.Socket) { return SocketSendFrom(s, buf, count, 0); }
        var src = (byte*)buf;
        long written = 0;
        for (; (ulong)written < count; written++)
        {
            if (!WriteByteBacking(s, src[written])) { break; }
        }
        return written;
    }

    /// <summary>POSIX <c>lseek(fd, offset, whence)</c> — reposition an fd's
    /// backing file stream; returns the resulting absolute offset, or -1 (ESPIPE)
    /// on a non-seekable slot (a console stream). Unlike <c>fseek</c> it returns
    /// the new offset, not 0. Used by chibi's <c>(chibi io)</c> custom ports.</summary>
    public static long lseek(int fd, long offset, int whence)
    {
        var s = SlotByFd(fd);
        if (s?.Stream is BackendDirectoryStream directory) return BackendDirectorySeek(directory, offset, whence);
        if (s == null || s.Kind != FileSlot.K.File || s.Stream is not { CanSeek: true } st)
        {
            errno = ESPIPE;
            return -1;
        }
        var origin = whence switch
        {
            SEEK_CUR => SeekOrigin.Current,
            SEEK_END => SeekOrigin.End,
            _ => SeekOrigin.Begin,
        };
        // A pending one-byte read-ahead would desync the position — drop it.
        s.Reader?.ResetPushback();
        try { var pos = st.Seek(offset, origin); s.Eof = false; return pos; }
        catch (IOException) { errno = EIO; return -1; }
    }

    /// <summary>The open slot behind a POSIX fd (dotcc fds ARE slot indices),
    /// or null. Shared by <c>close</c>/<c>read</c>/<c>write</c>/<c>fstat</c>.</summary>
    private static FileSlot? SlotByFd(int fd)
    {
        lock (_filesLock) { return (uint)fd < (uint)_files.Count ? _files[fd] : null; }
    }

    private static void CloseSlot(FileSlot slot)
    {
        FlushStdioBuffer(slot);
        slot.UserBuffer = null;
        slot.OutputBuffer = null;
        slot.BufferedBytes = slot.BufferCapacity = 0;
        // Every old FILE* must stay closed even after this fd number is reused.
        lock (_filesLock)
        {
            var descriptor = _files.IndexOf(slot);
            if (descriptor >= 3)
                foreach (var address in FileDescriptors.Handles)
                    if (((FILE*)address)->_slot == descriptor) ((FILE*)address)->_slot = -1;
        }
        if (slot.Kind == FileSlot.K.Pipe)
        {
            ClosePipe(slot);
            lock (_filesLock)
            {
                var index = _files.IndexOf(slot);
                if (index >= 3) _files[index] = null;
            }
            return;
        }
        if (slot.Kind == FileSlot.K.Socket)
        {
            // close(sockfd): Dispose closes the handle (sending FIN for a connected
            // TCP socket, like close(2)). Then the slot index is freed for reuse.
            slot.Socket?.Dispose();
            slot.Socket = null;
            lock (_filesLock)
            {
                var idx = _files.IndexOf(slot);
                if (idx >= 3) { _files[idx] = null; }
            }
            return;
        }
        if (slot.Kind is FileSlot.K.File or FileSlot.K.Directory)
        {
            try { slot.Writer?.Flush(); }
            finally
            {
                try { ReleaseFileBacking(slot); }
                finally
                {
                    slot.Stream = null;
                    slot.Writer = null;
                    slot.Reader = null;
                    // Mark the table entry reusable even if flushing failed.
                    lock (_filesLock)
                    {
                        var idx = _files.IndexOf(slot);
                        if (idx >= 3 || idx >= 0 && slot.Kind == FileSlot.K.Directory) { _files[idx] = null; }
                    }
                }
            }
        }
        else
        {
            // Std stream: flush, keep usable.
            (slot.Kind == FileSlot.K.Err ? Console.Error : Console.Out).Flush();
            lock (_filesLock)
            {
                var index = _files.IndexOf(slot);
                if (index >= 3) _files[index] = null;
            }
        }
    }

    private static int RegisterFileSlot(Stream stream)
    {
        var slot = new FileSlot { Kind = stream is BackendDirectoryStream ? FileSlot.K.Directory : FileSlot.K.File, Stream = stream,
            StatusFlags = stream.CanRead ? (stream.CanWrite ? 2 : 0) : 1 };
        lock (_filesLock)
        {
            for (var i = 3; i < _files.Count; i++)
            {
                if (_files[i] == null) { _files[i] = slot; return i; }
            }
            _files.Add(slot);
            return _files.Count - 1;
        }
    }

    private static void ConfigureStdioSlot(FileSlot slot, byte* mode, FileAccess access)
    {
        slot.StatusFlags = access == FileAccess.Read ? 0 : access == FileAccess.Write ? 1 : 2;
        if (*mode == (byte)'a') slot.StatusFlags |= 0x400;
        slot.DescriptorFlags = 0;
        for (var p = mode + 1; *p != 0; p++) if (*p == (byte)'e') slot.DescriptorFlags = 1;
        slot.StdioAccess = access == FileAccess.Read ? 1 : access == FileAccess.Write ? 2 : 3;
    }

    private static Stream? OpenStdioFile(string path, byte* mode, FileMode fileMode, FileAccess access)
    {
        if (OperatingSystem.IsLinux() && RuntimeInformation.ProcessArchitecture == Architecture.X64)
        {
            var flags = access == FileAccess.Read ? 0 : access == FileAccess.Write ? 1 : 2;
            if (*mode == (byte)'w') flags |= 0x40 | 0x200;
            if (*mode == (byte)'a') flags |= 0x40 | 0x400;
            if (fileMode == FileMode.CreateNew) flags |= 0x80;
            for (var p = mode + 1; *p != 0; p++) if (*p == (byte)'e') flags |= 0x80000;
            var stream = OpenLinuxStream(path, flags, 0x1b6); // 0666, filtered by the kernel umask
            if (stream is { CanSeek: true } && *mode == (byte)'a' && access == FileAccess.Write)
                stream.Seek(0, SeekOrigin.End);
            return stream;
        }
        try
        {
            var stream = new FileStream(path, fileMode, access, FileShare.ReadWrite | FileShare.Delete);
            if (*mode == (byte)'a' && access == FileAccess.Write) stream.Seek(0, SeekOrigin.End);
            return stream;
        }
        catch (ArgumentException) { errno = EINVAL; return null; }
        catch (FileNotFoundException) { errno = ENOENT; return null; }
        catch (DirectoryNotFoundException) { errno = ENOENT; return null; }
        catch (UnauthorizedAccessException) { errno = EACCES; return null; }
        catch (IOException) when (fileMode == FileMode.CreateNew && File.Exists(path)) { errno = EEXIST; return null; }
        catch (IOException) { errno = EIO; return null; }
    }

    private static bool ParseMode(byte* mode, out FileMode fileMode, out FileAccess access)
    {
        fileMode = FileMode.Open;
        access = FileAccess.Read;
        var first = *mode;
        bool plus = false, exclusive = false;
        for (var m = mode; *m != 0; m++)
        {
            if (*m == (byte)'+') plus = true;
            if (*m == (byte)'x') exclusive = true;
        }
        switch (first)
        {
            case (byte)'r':
                fileMode = FileMode.Open;
                access = plus ? FileAccess.ReadWrite : FileAccess.Read;
                return true;
            case (byte)'w':
                fileMode = exclusive ? FileMode.CreateNew : FileMode.Create;
                access = plus ? FileAccess.ReadWrite : FileAccess.Write;
                return true;
            case (byte)'a':
                fileMode = FileMode.OpenOrCreate;
                access = plus ? FileAccess.ReadWrite : FileAccess.Write;
                return true;
            default:
                return false;
        }
    }

    // ---------------------------------------------------------------------
    // Positioning + status
    // ---------------------------------------------------------------------

    /// <summary><c>SEEK_SET</c> / <c>SEEK_CUR</c> / <c>SEEK_END</c>.</summary>
    public const int SEEK_SET = 0, SEEK_CUR = 1, SEEK_END = 2;

    /// <summary>
    /// <c>fseek(stream, offset, whence)</c> — reposition a file stream.
    /// Returns 0 on success, nonzero on error (non-seekable console stream
    /// sets <c>errno</c> = ESPIPE). Clears EOF on success, per C.
    /// </summary>
    public static int fseek(FILE* stream, long offset, int whence)
    {
        var slot = Slot(stream);
        if (slot == null || slot.Kind != FileSlot.K.File || slot.Stream is not { CanSeek: true } st)
        {
            errno = ESPIPE;
            return -1;
        }
        if (!FlushStdioBuffer(slot)) return -1;
        var origin = whence switch
        {
            SEEK_CUR => SeekOrigin.Current,
            SEEK_END => SeekOrigin.End,
            _ => SeekOrigin.Begin,
        };
        // A pending one-byte read-ahead would desync the position — drop it.
        slot.Reader?.ResetPushback();
        try { st.Seek(offset, origin); }
        catch (IOException) { errno = EIO; return -1; }
        slot.Eof = false;
        return 0;
    }

    /// <summary><c>ftell(stream)</c> — current file position, or -1
    /// (errno ESPIPE) on a non-seekable stream.</summary>
    public static long ftell(FILE* stream)
    {
        var slot = Slot(stream);
        if (slot == null || slot.Kind != FileSlot.K.File || slot.Stream is not { CanSeek: true } st)
        {
            errno = ESPIPE;
            return -1;
        }
        var pos = st.Position + slot.BufferedBytes;
        // Account for a byte buffered by a pending Peek().
        if (slot.Reader is { HasPushback: true }) { pos -= 1; }
        return pos;
    }

    /// <summary><c>rewind(stream)</c> ≡ <c>fseek(stream, 0, SEEK_SET)</c> and
    /// clears the error indicator.</summary>
    public static void rewind(FILE* stream)
    {
        fseek(stream, 0, SEEK_SET);
        var slot = Slot(stream);
        if (slot != null) { slot.Err = false; }
    }

    /// <summary><c>feof(stream)</c> — nonzero once a read hit end-of-file.</summary>
    public static int feof(FILE* stream) => Slot(stream)?.Eof == true ? 1 : 0;

    /// <summary><c>ferror(stream)</c> — nonzero if an error occurred on the stream.</summary>
    public static int ferror(FILE* stream) => Slot(stream)?.Err == true ? 1 : 0;

    /// <summary><c>clearerr(stream)</c> — clear the EOF and error indicators.</summary>
    public static void clearerr(FILE* stream)
    {
        var slot = Slot(stream);
        if (slot != null) { slot.Eof = false; slot.Err = false; }
    }

    /// <summary>
    /// <c>ungetc(c, stream)</c> — push one byte back so the next read on
    /// <paramref name="stream"/> returns it (Lua's number/look-ahead lexing in
    /// liolib leans on this). C guarantees a single character of pushback, so a
    /// second <c>ungetc</c> with no intervening read fails — as does pushing
    /// <c>EOF</c>. Clears the EOF indicator on success. Returns the pushed byte,
    /// or <c>EOF</c> on failure. The byte is honored by <see cref="ReadByteFrom"/>
    /// (fgetc / getc / getchar / fgets).
    /// </summary>
    public static int ungetc(int c, FILE* stream)
    {
        var slot = Slot(stream);
        if (slot == null || c == -1 || slot.Pushback >= 0) { return -1; }
        slot.Pushback = c & 0xFF;
        slot.Eof = false;
        return c & 0xFF;
    }

    /// <summary>
    /// <c>setvbuf(stream, buf, mode, size)</c> — request a buffering mode
    /// (<c>_IOFBF</c>=0 / <c>_IOLBF</c>=1 / <c>_IONBF</c>=2; see include/stdio.h).
    /// Output buffering uses the caller's borrowed buffer, or owned managed
    /// storage when NULL. Unbuffered output flushes the backing after each write.
    /// Call before I/O, as required by C. Input retains the backing's read policy.
    /// </summary>
    public static int setvbuf(FILE* stream, byte* buf, int mode, int size)
    {
        var slot = Slot(stream);
        if (slot == null) { errno = EBADF; return -1; }
        if (mode < 0 || mode > 2 || mode != 2 && size <= 0) { errno = EINVAL; return -1; }
        byte[]? buffer = null;
        try { if (mode != 2 && buf == null) buffer = new byte[size]; }
        catch (OutOfMemoryException) { errno = ENOMEM; return -1; }
        if (!FlushStdioBuffer(slot)) return -1;
        slot.BufferMode = mode;
        slot.UserBuffer = mode == 2 ? null : buf;
        slot.OutputBuffer = buffer;
        slot.BufferCapacity = mode == 2 ? 0 : size;
        return 0;
    }

    public static void setbuf(FILE* stream, byte* buffer)
        => setvbuf(stream, buffer, buffer == null ? 2 : 0, 8192);

    private static void FlushBacking(FileSlot slot)
    {
        if (slot.Stream != null) slot.Stream.Flush();
        else if (slot.Kind == FileSlot.K.Out) Console.Out.Flush();
        else if (slot.Kind == FileSlot.K.Err) Console.Error.Flush();
    }

    private static bool FlushStdioBuffer(FileSlot slot)
    {
        try
        {
            var count = slot.BufferedBytes;
            slot.BufferedBytes = 0;
            for (var i = 0; i < count; i++)
                if (!WriteByteBacking(slot, slot.UserBuffer != null ? slot.UserBuffer[i] : slot.OutputBuffer![i]))
                { slot.Err = true; return false; }
            if (count != 0) FlushBacking(slot);
            return true;
        }
        catch (IOException) { errno = FileIoError(slot); slot.Err = true; return false; }
        catch (ObjectDisposedException) { errno = EBADF; slot.Err = true; return false; }
        catch (UnauthorizedAccessException) { errno = EACCES; slot.Err = true; return false; }
    }

    private static int FileIoError(FileSlot slot) => slot.Stream is FullDeviceStream ? ENOSPC : EIO;

    // Shared buffer returned by tmpnam(NULL); kept in sync with L_tmpnam.
    private static ref byte* _tmpnamBuf => ref FileDescriptors.Tmpnam;

    /// <summary>
    /// <c>tmpnam(s)</c> — produce a unique temp-file name (NOT created on disk,
    /// per C). Writes into <paramref name="s"/> (which must hold at least
    /// <c>L_tmpnam</c> bytes) when non-NULL, else into a shared internal buffer;
    /// returns that buffer, or <c>NULL</c> if no name fitting <c>L_tmpnam</c>
    /// could be produced. Uses the OS temp directory + a random component.
    /// </summary>
    public static byte* tmpnam(byte* s)
    {
        const int LTmpnam = 260;  // keep in sync with L_tmpnam in include/stdio.h
        var name = global::System.IO.Path.Combine(global::System.IO.Path.GetTempPath(), global::System.IO.Path.GetRandomFileName());
        var bytes = Encoding.UTF8.GetBytes(name);
        if (bytes.Length + 1 > LTmpnam) { return null; }
        // tmpnam(NULL) is non-reentrant by spec (shared buffer, overwritten by a
        // later call), but the buffer's one-time ALLOCATION must still be
        // race-free or two first-callers leak/clobber it. Guard just the alloc.
        if (s == null && _tmpnamBuf == null)
        {
            lock (_filesLock)
            {
                // `??=` isn't valid on a pointer type — explicit check.
                if (_tmpnamBuf == null) { _tmpnamBuf = (byte*)NativeMemory.Alloc((nuint)LTmpnam); }
            }
        }
        var dst = s != null ? s : _tmpnamBuf;
        for (var i = 0; i < bytes.Length; i++) { dst[i] = bytes[i]; }
        dst[bytes.Length] = 0;
        return dst;
    }

    /// <summary><c>fflush(stream)</c> — flush buffered output. <c>fflush(NULL)</c>
    /// flushes the console streams. Returns 0.</summary>
    public static int fflush(FILE* stream)
    {
        if (stream == null)
        {
            FileSlot?[] all;
            lock (_filesLock) all = _files.ToArray();
            var result = 0;
            foreach (var current in all)
                if (current != null && current.BufferMode >= 0)
                {
                    try { if (!FlushStdioBuffer(current)) result = -1; FlushBacking(current); }
                    catch (IOException) { current.Err = true; errno = EIO; result = -1; }
                }
            Console.Out.Flush();
            Console.Error.Flush();
            return result;
        }
        var slot = Slot(stream);
        try
        {
            if (slot == null) { errno = EBADF; return -1; }
            if (!FlushStdioBuffer(slot)) return -1;
            if (slot?.Kind == FileSlot.K.File) { slot.Writer?.Flush(); slot.Stream?.Flush(); }
            else if (slot?.Kind == FileSlot.K.Err) { Console.Error.Flush(); }
            else { Console.Out.Flush(); }
        }
        catch (IOException)
        {
            // The device couldn't accept the buffered data (a full disk, or the
            // synthetic /dev/full): C's fflush returns EOF and sets the error
            // indicator so file:flush reports (nil, msg, errno).
            errno = ENOSPC;
            if (slot != null) { slot.Err = true; }
            return -1;  // EOF
        }
        return 0;
    }

    // ---------------------------------------------------------------------
    // Binary I/O
    // ---------------------------------------------------------------------

    /// <summary>
    /// <c>fread(ptr, size, nmemb, stream)</c> — read up to
    /// <paramref name="nmemb"/> elements of <paramref name="size"/> bytes.
    /// Returns the number of complete elements read (&lt; nmemb at EOF). Sets
    /// the EOF indicator when input runs out.
    /// </summary>
    public static int fread(void* ptr, int size, int nmemb, FILE* stream)
    {
        if (size <= 0 || nmemb <= 0) { return 0; }
        var dst = (byte*)ptr;
        var total = (long)size * nmemb;
        long got = 0;
        for (; got < total; got++)
        {
            var b = ReadByteFrom(stream);
            if (b < 0) { break; }
            dst[got] = (byte)b;
        }
        return (int)(got / size); // complete elements
    }

    /// <summary>
    /// <c>fwrite(ptr, size, nmemb, stream)</c> — write
    /// <paramref name="nmemb"/> elements of <paramref name="size"/> bytes.
    /// Returns the number of complete elements written.
    /// </summary>
    public static int fwrite(void* ptr, int size, int nmemb, FILE* stream)
    {
        if (size <= 0 || nmemb <= 0) { return 0; }
        var src = (byte*)ptr;
        var total = (long)size * nmemb;
        // Stop at the first byte that can't be written (e.g. a read-only stream):
        // C's fwrite returns the count of COMPLETE elements written, and the
        // partial element is lost. errno / the error indicator are set by
        // WriteByteTo, so g_write's `numbytes < len` check reports the failure.
        long written = 0;
        for (; written < total; written++)
        {
            if (!WriteByteTo(stream, src[written])) { break; }
        }
        return (int)(written / size);
    }

    // ---------------------------------------------------------------------
    // Filesystem helpers
    // ---------------------------------------------------------------------

    /// <summary><c>remove(path)</c> — delete a file. 0 on success, -1 (errno) on failure.</summary>
    public static int remove(byte* path)
    {
        var p = ResolvePath(path);
        try
        {
            // .NET's File.Delete is a silent no-op on a missing file, but C's
            // remove() fails with ENOENT — so check existence first (Lua relies on
            // a second remove of the same file returning an error). remove() also
            // unlinks an empty directory in C, so handle that too.
            if (File.Exists(p)) { File.Delete(p); return 0; }
            if (Directory.Exists(p)) { Directory.Delete(p); return 0; }
            errno = ENOENT; return -1;
        }
        catch (FileNotFoundException) { errno = ENOENT; return -1; }
        catch (DirectoryNotFoundException) { errno = ENOENT; return -1; }
        catch (IOException) { errno = EIO; return -1; }
        catch (UnauthorizedAccessException) { errno = EACCES; return -1; }
    }

    /// <summary><c>rename(old, new)</c> — rename/move a file. 0 on success, -1 (errno) on failure.</summary>
    public static int rename(byte* oldp, byte* newp)
    {
        try
        {
            File.Move(ResolvePath(oldp),
                      ResolvePath(newp), overwrite: true);
            return 0;
        }
        catch (FileNotFoundException) { errno = ENOENT; return -1; }
        catch (DirectoryNotFoundException) { errno = ENOENT; return -1; }
        catch (IOException) { errno = EIO; return -1; }
        catch (UnauthorizedAccessException) { errno = EACCES; return -1; }
    }

    /// <summary>
    /// <c>tmpfile()</c> — open an anonymous read/write temp file that is
    /// deleted on close. Returns a <c>FILE*</c> or <c>null</c> on failure.
    /// </summary>
    public static FILE* tmpfile()
    {
        Stream stream;
        try
        {
            var path = global::System.IO.Path.GetTempFileName();
            stream = new FileStream(path, FileMode.Create, FileAccess.ReadWrite,
                FileShare.None, bufferSize: 4096, FileOptions.DeleteOnClose);
        }
        catch (IOException) { errno = EIO; return null; }
        var slot = RegisterFileSlot(stream);
        return AllocateFileHandle(slot);
    }

    // ---------------------------------------------------------------------
    // File-backed TextWriter / TextReader adapters
    // ---------------------------------------------------------------------

    /// <summary>
    /// Unbuffered <see cref="TextWriter"/> over a byte <see cref="Stream"/>:
    /// each write encodes UTF-8 straight to the stream, so formatted output
    /// (<c>fprintf</c>) and raw byte output (<c>fputc</c>/<c>fwrite</c>) on the
    /// same handle stay correctly ordered.
    /// </summary>
    private sealed class StreamFileWriter : TextWriter
    {
        private readonly FileSlot _s;
        public StreamFileWriter(FileSlot s) { _s = s; }
        public override Encoding Encoding => Encoding.UTF8;

        public override void Write(char c)
        {
            if (c < 0x80) { if (!WriteByteSlot(_s, (byte)c)) throw new IOException(); return; }
            Span<char> one = stackalloc char[1] { c };
            Span<byte> buf = stackalloc byte[4];
            var n = Encoding.UTF8.GetBytes(one, buf);
            for (var i = 0; i < n; i++) if (!WriteByteSlot(_s, buf[i])) throw new IOException();
        }

        public override void Write(string? value)
        {
            if (string.IsNullOrEmpty(value)) { return; }
            var bytes = Encoding.UTF8.GetBytes(value);
            foreach (var b in bytes) if (!WriteByteSlot(_s, b)) throw new IOException();
        }

        public override void Flush() { if (!FlushStdioBuffer(_s)) throw new IOException(); FlushBacking(_s); }
    }

    /// <summary>
    /// Byte-at-a-time <see cref="TextReader"/> over a <see cref="Stream"/> with a
    /// one-byte pushback for <see cref="Peek"/>. Returns each byte as a char
    /// (0..255) — exact for <c>fgetc</c>/<c>fgets</c> (byte-oriented) and for
    /// ASCII <c>fscanf</c>; it deliberately does not decode multi-byte UTF-8
    /// (which would desync the byte position that <c>ftell</c> reports).
    /// </summary>
    /// <summary>
    /// Synthetic backing for the Unix <c>/dev/full</c> device: writes are accepted
    /// (as if buffered into the kernel) but <c>Flush</c> always fails with a
    /// "no space" <see cref="IOException"/> — which <see cref="fflush"/> turns into
    /// an EOF result. Reads return EOF. <c>Dispose</c> never flushes (so
    /// <c>fclose</c> on it still succeeds), matching what testes/files.lua expects.
    /// </summary>
    private sealed class FullDeviceStream : Stream
    {
        public override bool CanRead => true;
        public override bool CanWrite => true;
        public override bool CanSeek => false;
        public override long Length => 0;
        public override long Position { get => 0; set { } }
        public override void Write(byte[] buffer, int offset, int count) { }  // accepted
        public override void WriteByte(byte value) { }                        // accepted
        public override int Read(byte[] buffer, int offset, int count) => 0;  // EOF
        public override int ReadByte() => -1;                                 // EOF
        public override void Flush() => throw new IOException("No space left on device");
        public override long Seek(long offset, SeekOrigin origin) => 0;
        public override void SetLength(long value) { }
        protected override void Dispose(bool disposing) { /* never flushes / throws */ }
    }

    internal sealed class StreamFileReader : TextReader
    {
        private readonly Stream _s;
        private int _pushed = -1;
        public StreamFileReader(Stream s) { _s = s; }

        public bool HasPushback => _pushed >= 0;
        public void ResetPushback() => _pushed = -1;

        public override int Peek()
        {
            // A write-only stream (file opened "w"/"a") can't be read — C's fgetc
            // returns EOF there (and sets the error indicator) rather than faulting,
            // so report EOF instead of letting Stream.ReadByte throw.
            if (_pushed < 0)
            {
                if (!_s.CanRead) { return -1; }
                _pushed = _s.ReadByte();
            }
            return _pushed;
        }

        public override int Read()
        {
            if (_pushed >= 0) { var r = _pushed; _pushed = -1; return r; }
            if (!_s.CanRead) { return -1; }  // write-only stream → EOF, not a throw
            return _s.ReadByte();
        }
    }
}


