            if (pattern[i] == '\\' && i + 1 < pattern.Length) i++;
            result.Append(pattern[i]);
        }
        return result.ToString();
    }
    private static bool GlobHasMagic(byte[] pattern, bool noEscape)
    {
        for (var i = 0; i < pattern.Length; i++)
