    /// <summary>
    /// <c>atof(nptr)</c> — <c>strtod(nptr, NULL)</c>: parse a leading double,
    /// ignoring where it ends. No error reporting (matches C).
    /// </summary>
    public static double atof(byte* nptr) => strtod(nptr, null);

