    public static SprintfBuilder snprintf(byte* dst, int n, byte* fmt) => new SprintfBuilder(dst, fmt, capacity: n <= 0 ? 0 : n - 1, terminate: n > 0);

    /// <summary>
    /// <c>fscanf(stream, fmt)</c> — start a fluent scan chain reading from
    /// <paramref name="stream"/>. Each <see cref="ScanfReader.Read(int*)"/>
    /// / <see cref="ScanfReader.Read(double*)"/> /
    /// <see cref="ScanfReader.Read(byte*)"/> consumes the next <c>%</c>
    /// spec and writes the parsed value. <see cref="ScanfReader.Done"/>
    /// returns the count of successful matches.
    /// </summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static ScanfReader fscanf(FILE* stream, byte* fmt) => new ScanfReader(ReaderFor(stream), fmt);

    /// <summary><c>scanf(fmt)</c> ≡ <c>fscanf(stdin, fmt)</c>.</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static ScanfReader scanf(byte* fmt) => fscanf(stdin, fmt);

    /// <summary>
    /// <c>sscanf(src, fmt)</c> — parse from the NUL-terminated UTF-8
    /// byte buffer <paramref name="src"/> instead of a stream. Equivalent
    /// to wrapping <paramref name="src"/> in a <see cref="StringReader"/>
    /// and calling <see cref="fscanf"/>.
    /// </summary>
    public static ScanfReader sscanf(byte* src, byte* fmt)
    {
        var len = strlen(src);
        var s = global::System.Text.Encoding.UTF8.GetString(src, len);
        return new ScanfReader(new StringReader(s), fmt);
    }

    // ---------------------------------------------------------------------
    // String literal lowering
    // ---------------------------------------------------------------------

    /// <summary>Return the address of literal RVA data without retaining its owner.
    /// Used by default emission; --literal-pool selects rooted translated storage instead.
    /// The caller must ensure the backing data stays at a fixed address and remains alive.</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static byte* L(ReadOnlySpan<byte> u8) =>
        (byte*)Unsafe.AsPointer(ref MemoryMarshal.GetReference(u8));

    /// <summary>Typed counterpart of <see cref="L(ReadOnlySpan{byte})"/> with the same
    /// backing-storage lifetime requirements.</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static T* L<T>(ReadOnlySpan<T> data) where T : unmanaged =>
        (T*)Unsafe.AsPointer(ref MemoryMarshal.GetReference(data));

    // char16_t (UTF-16) string-literal pool. C# has no `u16` literal.
    // Instead pin its UTF-16 data on the Pinned Object Heap ONCE, cached per
    // distinct literal — a program-lifetime pool, mirroring how C places string
    // literals in .rodata. Pinning per use would leak a frame under a loop.
    private static readonly global::System.Collections.Concurrent.ConcurrentDictionary<string, IntPtr> _u16Literals = new ConcurrentDictionary<string, IntPtr>(StringComparer.Ordinal);

    /// <summary><c>L16("…")</c> — return a stable <c>char*</c> (= char16_t*) to a
    /// pinned, NUL-terminated copy of a C11 <c>u"…"</c> literal's UTF-16 data. The
    /// argument is a C# string literal that already includes its trailing NUL char;
    /// each distinct literal is pinned once on the POH and rooted for the program's
    /// life (so the pointer never moves), exactly like <see cref="GlobalArrayFrom{T}"/>.</summary>
    public static char* L16(string s)
    {
        if (_u16Literals.TryGetValue(s, out var hit)) { return (char*)hit; }   // lock-free hot path
        // Miss: pin a copy and publish atomically. Two threads racing the same new
        // literal both pin; only the winner roots its array (so the pooled pointer
        // stays valid for the program's life). The loser's array is unreferenced once
        // we return — pinning prevents movement, not collection, so the GC reclaims
        // it; nothing leaks.
        var arr = GC.AllocateUninitializedArray<char>(s.Length, pinned: true);
        s.CopyTo(arr);
        var ptr = (IntPtr)Unsafe.AsPointer(ref MemoryMarshal.GetArrayDataReference(arr));
        var actual = _u16Literals.GetOrAdd(s, ptr);
        if (actual == ptr) { lock (_globalArrayRoots) { _globalArrayRoots.Add(arr); } }
        return (char*)actual;
    }

    // char32_t (UTF-32) string-literal pool — the 32-bit sibling of the L16 pool.
    // C# has no `u32` literal; pin UTF-32 data on the POH once per distinct literal.
    private static readonly global::System.Collections.Concurrent.ConcurrentDictionary<string, IntPtr> _u32Literals = new ConcurrentDictionary<string, IntPtr>(StringComparer.Ordinal);

    /// <summary><c>L32("…")</c> — return a stable <c>uint*</c> (= char32_t*) to a
    /// pinned, NUL-terminated copy of a C11 <c>U"…"</c> literal's UTF-32 data. The
    /// argument is a C# (UTF-16) string literal that already includes its trailing NUL
    /// char; <see cref="System.Text.Encoding.UTF32"/> folds it — surrogate pairs and
    /// all — into little-endian 4-byte code units (dotcc is LP64/LE, so the encoded
    /// byte stream IS the <c>uint</c> array). Each distinct literal is pinned once on
    /// the POH and rooted for the program's life, exactly like <see cref="L16"/>.</summary>
    public static uint* L32(string s)
    {
        if (_u32Literals.TryGetValue(s, out var hit)) { return (uint*)hit; }   // lock-free hot path
        // Reuse the BCL's UTF-16 → UTF-32 fold: GetBytes yields LE 4-byte scalars,
        // no BOM, and encodes the trailing '\0' as a zero code unit (the terminator).
        var bytes = global::System.Text.Encoding.UTF32.GetBytes(s);
        var arr = GC.AllocateUninitializedArray<uint>(bytes.Length / 4, pinned: true);
        global::System.Buffer.BlockCopy(bytes, 0, arr, 0, bytes.Length);
        var ptr = (IntPtr)Unsafe.AsPointer(ref MemoryMarshal.GetArrayDataReference(arr));
        var actual = _u32Literals.GetOrAdd(s, ptr);
        if (actual == ptr) { lock (_globalArrayRoots) { _globalArrayRoots.Add(arr); } }
        return (uint*)actual;
    }

    // ── <signal.h> ─────────────────────────────────────────────────────

    private sealed class SignalRegistration(delegate*<int, void> handler, RuntimeContext owner) : IDisposable
    {
        internal readonly delegate*<int, void> Handler = handler;
        internal readonly RuntimeContext Owner = owner;
        private readonly IDisposable lease = owner.RetainLease();
        public void Dispose() => lease.Dispose();
    }

    private static readonly object signalGate = new object();
    private static SignalRegistration? sigintRegistration;
    private static bool sigintSubscribed;
    [ThreadStatic] private static bool deliveringSigint;
    [ThreadStatic] private static bool pendingSigint;

    /// <summary><c>signal(sig, func)</c> — register a signal handler.
    /// Only SIGINT (2) is supported; uses .NET
    /// <see cref="Console.CancelKeyPress"/>. Dispositions are process-wide;
    /// a handler retains its installing context until replaced or reset.</summary>
    public static unsafe delegate*<int, void> signal(
        int sig, delegate*<int, void> func)
    {
        // Other signals have never had a managed signal() handler backend.
        // Report unsupported registration instead of false SIG_DFL success.
        if (sig != 2 || (nint)func == -1) { errno = EINVAL; return (delegate*<int, void>)(nint)(-1); }
        var next = func == null ? null : new SignalRegistration(func, RuntimeState);
        SignalRegistration? previous;
        try
        {
            lock (signalGate)
            {
                if (next != null && !sigintSubscribed)
                {
                    Console.CancelKeyPress += OnSigint;
                    sigintSubscribed = true;
                }
                else if (next == null && sigintSubscribed)
                {
                    Console.CancelKeyPress -= OnSigint;
                    sigintSubscribed = false;
                }
                previous = sigintRegistration;
                sigintRegistration = next;
            }
        }
        catch { next?.Dispose(); throw; }
        // In-flight delivery acquired its own Enter() binding under the gate.
        var result = previous == null ? null : previous.Handler;
        previous?.Dispose();
        return result;
    }

    private static bool DeliverSigint()
    {
        // POSIX defers the same signal while its handler runs. Coalesce a
        // reentrant raise and observe reinstallation after the handler returns.
        if (deliveringSigint) { pendingSigint = true; return true; }
        deliveringSigint = true;
        try
        {
            do
            {
                pendingSigint = false;
                SignalRegistration? registration;
                RuntimeBinding binding = default;
                lock (signalGate)
                {
                    registration = sigintRegistration;
                    if (registration != null && (nint)registration.Handler != 1)
                        binding = registration.Owner.Enter();
                }
                if (registration == null)
                {
                    // The caller must apply SIG_DFL, including a deferred
                    // signal whose handler selected default before returning.
                    return false;
                }
                // Never execute a callback under the disposition gate.
                using (binding)
                {
                    if ((nint)registration.Handler != 1) registration.Handler(2);
                }
            } while (pendingSigint);
            return true;
        }
        finally { pendingSigint = false; deliveringSigint = false; }
    }

    private static unsafe void OnSigint(object? sender, ConsoleCancelEventArgs e)
    {
        if (DeliverSigint()) e.Cancel = true;
    }
}


