                    throw new IOException("Invalid host creation mask in /proc/self/status.");
                mask = (mask << 3) | (uint)(digit - '0');
            }
            return mask;
        }
        throw new PlatformNotSupportedException("Linux procfs does not expose the host creation mask.");
    }

