        static extern int ResizeFile(SafeFileHandle handle, long size);
    }

    /// <summary><c>mkfifo(path, mode)</c> — create a named pipe (FIFO). Forwards
    /// to <c>mkfifo(3)</c> on POSIX. Windows named pipes aren't filesystem
    /// objects (no <c>mkfifo</c> equivalent that a path-based open could reopen),
    /// so on Windows it stays an honest EPERM.</summary>
    public static int mkfifo(byte* path, uint mode)
    {
        if (OperatingSystem.IsWindows()) { errno = EPERM; return -1; }
        if (path == null) { errno = EFAULT; return -1; }
        fixed (byte* name = Encoding.UTF8.GetBytes(ResolvePath(path) + "\0"))
            if (PosixMkfifo(name, mode) == 0) { return 0; }
        errno = Marshal.GetLastPInvokeError();
        return -1;
    }

    [DllImport("libc", EntryPoint = "mkfifo", SetLastError = true)]
    private static extern int PosixMkfifo(byte* path, uint mode);

    /// <summary>Duplicate an owned file/console descriptor with a shared open
    /// file description and independent descriptor close lifetime.</summary>
    public static int dup(int fd) => DuplicateDescriptor(fd, null);

    /// <inheritdoc cref="dup(int)"/>
    public static int dup2(int oldfd, int newfd) => DuplicateDescriptor(oldfd, newfd);

    // ---- helpers -----------------------------------------------------------

    /// <summary>Decode a NUL-terminated UTF-8 C string to a managed string
    /// (empty for <c>null</c>).</summary>
    private static string Str(byte* s) => s == null ? string.Empty : Encoding.UTF8.GetString(s, strlen(s));

    /// <summary>Apply Unix permission bits where the host supports them; ignore
    /// failure (a path that vanished) — chmod is best-effort. On Windows there
    /// are no Unix mode bits, so it's a no-op: <see cref="File.SetUnixFileMode(string, UnixFileMode)"/>
    /// is unsupported there (the explicit OS guard both expresses that and
    /// satisfies CA1416, rather than catching the PlatformNotSupportedException).</summary>
    private static void TrySetUnixMode(string path, int mode)
    {
        if (OperatingSystem.IsWindows()) { return; }
        try { File.SetUnixFileMode(path, (UnixFileMode)(mode & 0xFFF)); }
        catch { /* a path that vanished mid-call — best-effort */ }
    }
}


