        {
            if (PosixGetrusage(who, usage) == 0) { return 0; }
            errno = Marshal.GetLastPInvokeError();
            return -1;
        }

        // struct rusage as longs: [0]=ru_utime.tv_sec [1]=.tv_usec
        // [2]=ru_stime.tv_sec [3]=.tv_usec [4]=ru_maxrss, rest 0.
        new Span<byte>(usage, 144).Clear();
        var ru = (long*)usage;
