        switch (spec.Conv)
        {
            case (byte)'d': case (byte)'i':
                s = PadInt(v, spec, ci);
                break;
            case (byte)'u': s = PadInt((ulong)v, spec, ci); break; // unsigned bit pattern
            case (byte)'x': s = (spec.Alt ? "0x" : "") + v.ToString("x", ci); break;
            case (byte)'X': s = (spec.Alt ? "0X" : "") + v.ToString("X", ci); break;
            case (byte)'o': s = AltOctal(FormatOctal((ulong)v), spec); break; // # handled by AltOctal
            case (byte)'f': case (byte)'e': case (byte)'E': case (byte)'g': case (byte)'G':
                s = FormatFloat((double)v, spec, ci);
                break;
            default: s = v.ToString(ci); break;
        }
        Emit(ApplyWidth(s, spec));
        return this;
    }

    public PrintfBuilder Arg(ulong v)
    {
        var spec = ConsumeUntilSpec();
        if (ConsumeDynamicField(ref spec, unchecked((long)v))) return this;
        var ci = CultureInfo.InvariantCulture;
        string s;
        switch (spec.Conv)
        {
            case (byte)'u':
            case (byte)'d': case (byte)'i':
                s = v.ToString(ci);
                break;
            case (byte)'x': s = v.ToString("x", ci); break;
            case (byte)'X': s = v.ToString("X", ci); break;
            case (byte)'o': s = AltOctal(FormatOctal(v), spec); break;
            default: s = v.ToString(ci); break;
        }
        Emit(ApplyWidth(s, spec));
        return this;
    }

    /// <summary>
    /// <c>uint</c> → routed through <see cref="Arg(long)"/>. The implicit
    /// promotion preserves the full 32-bit range; printf semantics don't
    /// distinguish signed/unsigned at the format-string level.
    /// </summary>
    public PrintfBuilder Arg(uint v) => Arg((long)v);

    public PrintfBuilder Arg(byte* v)
    {
        var spec = ConsumeUntilSpec();
        string s;
        if (spec.Conv == (byte)'s' && v != null)
        {
            var len = 0;
            // C precision bounds bytes read, including non-terminated slices.
            while ((spec.Precision < 0 || len < spec.Precision) && v[len] != 0) { len++; }
            s = (_byteOutput ? global::System.Text.Encoding.Latin1 : global::System.Text.Encoding.UTF8).GetString(v, len);
        }
        else if (spec.Conv == (byte)'p')
        {
            // glibc-shaped %p: a null pointer is "(nil)"; otherwise "0x" + the address
            // in lowercase hex with no leading zeros. Matches clang/gcc (and the wat
            // backend), so the same C program prints the same shape on both targets.
            s = v == null
                ? "(nil)"
                : "0x" + ((ulong)v).ToString("x", CultureInfo.InvariantCulture);
        }
        else if (v == null)
        {
            s = "(null)";
        }
        else
        {
            // Wrong spec for a pointer → print the address. System-qualified
            // because emitted user code can `typedef int* IntPtr;` and
            // shadow the BCL type at file scope via `using unsafe IntPtr = int*;`.
            s = ((global::System.IntPtr)v).ToString("X");
        }
        Emit(ApplyWidth(s, spec));
        return this;
    }

    /// <summary>
    /// A <c>void*</c> (or any typed <c>T*</c>, which implicitly converts to
    /// <c>void*</c>) argument — typically a <c>%p</c> spec. Reuses the
    /// <see cref="Arg(byte*)"/> path (glibc-shaped <c>0x…</c>/<c>(nil)</c> for
    /// <c>%p</c>, address-print for other non-<c>%s</c> specs). A dedicated overload
    /// is required because <c>void*</c> does NOT implicitly convert to <c>byte*</c>
    /// in C#, so without it a <c>%p</c> pointer arg fails to bind.
    /// </summary>
    public PrintfBuilder Arg(void* v) => Arg((byte*)v);

    /// <summary>
    /// A wide-string (<c>wchar_t*</c> = C# <c>char*</c>) argument — the wide
    /// <c>%s</c> / <c>%ls</c> spec used by <c>wprintf</c>/<c>fwprintf</c>/<c>swprintf</c>
    /// (whose format is transcoded to UTF-8, so the spec is parsed identically; only
    /// the argument is UTF-16). Reads the NUL-terminated UTF-16 string and writes it,
    /// honoring precision. Narrow <c>printf</c> never passes a <c>char*</c> (its
    /// <c>%s</c> is a <c>byte*</c>), so this overload is wide-only.
    /// </summary>
    public PrintfBuilder Arg(char* v)
    {
        var spec = ConsumeUntilSpec();
        string s;
        if ((spec.Conv == (byte)'s' || spec.Conv == (byte)'S') && v != null)
        {
            var len = 0;
            while (v[len] != 0) { len++; }
            s = new string(v, 0, len);
            if (spec.Precision >= 0 && spec.Precision < s.Length) { s = s[..spec.Precision]; }
        }
        else if (v == null)
        {
            s = "(null)";
        }
        else
        {
            s = ((global::System.IntPtr)v).ToString("X");
        }
        Emit(ApplyWidth(s, spec));
        return this;
    }

    /// <summary>
    /// Flush the literal text remaining after the last consumed <c>%</c>
    /// spec and return the number of UTF-8 bytes written across the whole
    /// format — printf's C99 §7.21.6.3 return value. (dotcc never signals the
    /// negative output-error case; the sinks are managed writers that throw.)
    /// </summary>
    public int Done()
    {
        while (*_fmt != 0)
        {
            if (*_fmt == (byte)'%' && _fmt[1] == (byte)'%')
            {
                _w.Write('%');
                _count++;
                _fmt += 2;
                continue;
            }
            WriteUtf8Codepoint(ref _fmt);
        }
        return _count;
    }

    private Spec ConsumeUntilSpec()
    {
        if (_hasPendingSpec) { _hasPendingSpec = false; return _pendingSpec; }
        Libc.VaList unused = default;
        return ConsumeUntilSpec(unused, false, out _);
    }

    // Fluent arguments arrive one at a time. Width/precision stars consume an
    // integer argument but retain this conversion for its eventual value.
    private bool ConsumeDynamicField(ref Spec spec, long value)
    {
        if (spec.WidthArgument)
        {
            spec.WidthArgument = false;
            spec.Width = checked((int)value);
            if (spec.Width < 0) { spec.Left = true; spec.Width = checked(-spec.Width); }
        }
        else if (spec.PrecisionArgument)
        {
            spec.PrecisionArgument = false;
            spec.Precision = value < 0 ? -1 : checked((int)value);
        }
        else return false;
        _pendingSpec = spec;
        _hasPendingSpec = true;
        return true;
    }

    private Spec ConsumeUntilSpec(scoped Libc.VaList arguments, bool cursor, out int consumed)
    {
        consumed = 0;
        while (*_fmt != 0)
        {
            if (*_fmt == (byte)'%')
            {
                _fmt++;
                if (*_fmt == (byte)'%')
                {
                    _w.Write('%');
                    _count++;
                    _fmt++;
                    continue;
                }
                return ParseSpec(arguments, cursor, out consumed);
            }
            if (cursor) { _w.Write((char)*_fmt++); _count++; }
            else WriteUtf8Codepoint(ref _fmt);
        }
        return new Spec { Conv = 0, Width = -1, Precision = -1 };
    }

    /// <summary>
    /// Parse <c>[flags][width][.precision][length]conv</c> from the byte
    /// stream starting just past the leading <c>%</c>. Advances
    /// <c>_fmt</c> through the entire spec, including the conversion char.
    /// </summary>
    private Spec ParseSpec(scoped Libc.VaList arguments, bool cursor, out int consumed)
    {
        consumed = 0;
        var s = new Spec { Width = -1, Precision = -1 };
        while (*_fmt != 0)
        {
            switch (*_fmt)
            {
                case (byte)'-': s.Left = true; _fmt++; continue;
                case (byte)'+': s.Plus = true; _fmt++; continue;
                case (byte)' ': s.Space = true; _fmt++; continue;
                case (byte)'0': s.Zero = true; _fmt++; continue;
                case (byte)'#': s.Alt = true; _fmt++; continue;
            }
            break;
        }
        while (*_fmt >= (byte)'0' && *_fmt <= (byte)'9')
        {
            if (s.Width < 0) { s.Width = 0; }
            s.Width = s.Width * 10 + (*_fmt - (byte)'0');
            _fmt++;
        }
        if (*_fmt == (byte)'*')
        {
            _fmt++;
            if (cursor)
            {
                s.Width = (int)arguments.Next();
                consumed++;
                if (s.Width < 0) { s.Left = true; s.Width = checked(-s.Width); }
            }
            else s.WidthArgument = true;
        }
        if (*_fmt == (byte)'.')
        {
            _fmt++;
            s.Precision = 0;
            while (*_fmt >= (byte)'0' && *_fmt <= (byte)'9')
            {
                s.Precision = s.Precision * 10 + (*_fmt - (byte)'0');
                _fmt++;
            }
        }
        if (*_fmt == (byte)'*')
        {
            _fmt++;
            if (cursor)
            {
                s.Precision = (int)arguments.Next();
                consumed++;
                if (s.Precision < 0) s.Precision = -1;
            }
            else s.PrecisionArgument = true;
        }
        if (*_fmt == (byte)'l' || *_fmt == (byte)'L' || *_fmt == (byte)'h'
            || *_fmt == (byte)'z' || *_fmt == (byte)'j' || *_fmt == (byte)'t')
        {
            s.Length = *_fmt++;
            if ((s.Length == (byte)'l' || s.Length == (byte)'h') && *_fmt == s.Length)
            { s.DoubleLength = true; _fmt++; }
        }
        s.Conv = *_fmt;
        if (s.Conv != 0) { _fmt++; }
        return s;
    }

    private static string FormatFloat(double v, Spec spec, CultureInfo ci)
    {
        var prec = spec.Precision >= 0 ? spec.Precision : 6;
        var s = spec.Conv switch
        {
            (byte)'e' => v.ToString("e" + prec.ToString(ci), ci),
            (byte)'E' => v.ToString("E" + prec.ToString(ci), ci),
            (byte)'g' => spec.Precision >= 0
                ? v.ToString("g" + prec.ToString(ci), ci)
                : v.ToString("g", ci),
            (byte)'G' => spec.Precision >= 0
                ? v.ToString("G" + prec.ToString(ci), ci)
                : v.ToString("G", ci),
            _ => v.ToString("F" + prec.ToString(ci), ci),
        };
        // '#' flag for floats: force a decimal point even when precision is 0
        // (e.g. %#.0f with value 100 → "100.")
        if (spec.Alt && !s.Contains('.')) { s += "."; }
        if (spec.Plus && v >= 0) { s = "+" + s; }
        else if (spec.Space && v >= 0) { s = " " + s; }
        return s;
    }

    private static string ApplyWidth(string s, Spec spec)
    {
        if (spec.Width <= 0 || s.Length >= spec.Width) { return s; }
        if (spec.Left) { return s.PadRight(spec.Width, ' '); }
        // Zero-padding only when right-aligned and no precision (per C).
        // When the value carries a leading sign, the zero-pad goes between
        // the sign and the digits — handle that case.
        if (spec.Zero)
        {
            if (s.Length > 0 && (s[0] == '-' || s[0] == '+' || s[0] == ' '))
            {
                return s[0] + new string('0', spec.Width - s.Length) + s[1..];
            }
            return s.PadLeft(spec.Width, '0');
        }
        return s.PadLeft(spec.Width, ' ');
    }

    private void WriteUtf8Codepoint(ref byte* p)
    {
        var b = *p;
        // Allocating byte-buffer formatting preserves every original C byte,
        // including non-UTF8 %s data and multibyte format literals.
        if (_byteOutput) { _w.Write((char)b); _count++; p++; return; }
        if (b < 0x80) { _w.Write((char)b); _count++; p++; return; }
        var len = 1;
        if ((b & 0xE0) == 0xC0) { len = 2; }
        else if ((b & 0xF0) == 0xE0) { len = 3; }
        else if ((b & 0xF8) == 0xF0) { len = 4; }
        _w.Write(global::System.Text.Encoding.UTF8.GetString(p, len));
        _count += len;
        p += len;
    }
}


#nullable restore
// ---- ProcessServicesLib.cs ----
#nullable enable


public static unsafe partial class Libc
{
    public sealed partial class RuntimeContext
    {
        internal int GetoptIndex = 1;
    }

    /// <summary>POSIX option-parser cursor. This is process state, shared by
    /// threads bound to the same owner, and initially one for each owner.
    /// This storage does not implement getopt itself.</summary>
    public static ref int optind => ref RuntimeState.GetoptIndex;

    /// <summary>The actual host memory page size, in bytes, matching
    /// sysconf(_SC_PAGESIZE). Successful queries leave errno unchanged.</summary>
    public static int getpagesize() => Environment.SystemPageSize;

    /// <summary>The exact read-only locale inventory command uses the reviewed
    /// host utility. Other commands require an embedder's in-process callbacks;
    /// this surface never starts a shell or a native database backend.</summary>
    public static FILE* popen(byte* command, byte* mode)
    {
        if (command == null || mode == null) { errno = EFAULT; return null; }
        // The Linux-shaped surface also accepts the close-on-exec suffix.
        if ((*mode != (byte)'r' && *mode != (byte)'w') ||
            (mode[1] != 0 && (mode[1] != (byte)'e' || mode[2] != 0)))
        { errno = EINVAL; return null; }
        if (*mode == (byte)'r' && LocaleInventoryCommand(command))
            return OpenLocaleInventory(mode);
        errno = ENOTSUP;
        return null;
    }

    /// <summary>Close an owner-local locale inventory stream and return its
    /// actual POSIX wait status. Never close an ordinary caller's stream.</summary>
    public static int pclose(FILE* stream)
    {
        if (Slot(stream) is null) { errno = EBADF; return -1; }
        return CloseLocaleInventory(stream);
    }
}


#nullable restore
// ---- ProcessSignalLib.cs ----
#nullable enable



/// <summary>
/// The POSIX process-control and signal surface (<c>&lt;unistd.h&gt;</c>
/// fork/exec, <c>&lt;sys/wait.h&gt;</c>, <c>&lt;signal.h&gt;</c>) chibi-scheme's
/// <c>(chibi process)</c> binds to. .NET has no <c>fork</c> and the runtime owns
/// in-process signal *handling*, so fork/exec/wait stay honest stubs that compile
/// + let the module LOAD. The process *identity* and *targeting* primitives are
/// faithful, though: <c>getpid</c>/<c>getppid</c> report the real OS pids, the
/// <c>sigset_t</c> manipulators are real bitset ops, and <c>kill</c> forwards to the OS (POSIX
/// <c>kill(2)</c> / Windows OpenProcess+TerminateProcess) so the portable
/// <c>kill(pid, 0)</c> existence probe and a SIGKILL/SIGTERM are real.
/// The R7RS suite uses
/// command-line / exit / environment access, not fork/exec — so the
/// stubs are never exercised by it (and fail loudly, EPERM/-1, if a program
/// does call them).
/// </summary>
public static unsafe partial class Libc
{
    // ---- <unistd.h> process control ---------------------------------------

    /// <summary><c>getpid()</c> — the current process id (faithful).</summary>
    public static int getpid() => Environment.ProcessId;

    /// <summary><c>getppid()</c> — parent process id. POSIX <c>getppid(2)</c> is
    /// exact. Windows has no direct API, so we scan the toolhelp process snapshot
    /// for our own entry and read its parent field. Returns 0 if the parent can't
    /// be determined (snapshot failed, or our entry isn't listed).</summary>
    public static int getppid()
    {
        if (OperatingSystem.IsWindows()) { return WinGetParentPid(); }
        return PosixGetppid();
    }

    [DllImport("libc", EntryPoint = "getppid")]
    private static extern int PosixGetppid();

    // ---- Windows parent-pid via the toolhelp process snapshot --------------
    // A blittable PROCESSENTRY32W (primitives + a fixed WCHAR buffer) and the
    // toolhelp APIs: no marshalling stub, so it stays AOT-clean and survives the
    // runtime-block splice (same reasoning as link()'s [DllImport]).

    [StructLayout(LayoutKind.Sequential)]
    private struct PROCESSENTRY32W
    {
        public uint dwSize;
        public uint cntUsage;
        public uint th32ProcessID;
        public nuint th32DefaultHeapID;    // ULONG_PTR
        public uint th32ModuleID;
        public uint cntThreads;
        public uint th32ParentProcessID;
        public int pcPriClassBase;
        public uint dwFlags;
        public fixed char szExeFile[260];  // MAX_PATH
    }

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern IntPtr CreateToolhelp32Snapshot(uint dwFlags, uint th32ProcessID);

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern int Process32FirstW(IntPtr hSnapshot, ref PROCESSENTRY32W lppe);

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern int Process32NextW(IntPtr hSnapshot, ref PROCESSENTRY32W lppe);

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern int CloseHandle(IntPtr hObject);

    [DllImport("kernel32.dll")]
    private static extern uint GetCurrentProcessId();

    /// <summary>Parent pid via the toolhelp snapshot: find our own pid's entry
    /// and return its <c>th32ParentProcessID</c>. 0 if unavailable.</summary>
    private static int WinGetParentPid()
    {
        const uint TH32CS_SNAPPROCESS = 0x00000002;
        var self = GetCurrentProcessId();
        var snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
        if (snap == IntPtr.Zero || snap == new IntPtr(-1)) { return 0; }
        try
        {
            var pe = new PROCESSENTRY32W { dwSize = (uint)sizeof(PROCESSENTRY32W) };
            if (Process32FirstW(snap, ref pe) == 0) { return 0; }
            do
            {
                if (pe.th32ProcessID == self) { return (int)pe.th32ParentProcessID; }
            }
            while (Process32NextW(snap, ref pe) != 0);
            return 0;
        }
        finally { CloseHandle(snap); }
    }

    /// <summary><c>sleep(seconds)</c> — block the calling thread; returns 0 (no
    /// signal interrupts it on .NET, so the full interval always elapses).</summary>
    public static uint sleep(uint seconds)
    {
        global::System.Threading.Thread.Sleep((int)Math.Min(seconds, int.MaxValue / 1000) * 1000);
        return 0;
    }

    /// <summary><c>fork()</c> — no .NET primitive; fails with EPERM (return -1).
    /// A managed runtime can't duplicate its own address space.</summary>
    public static int fork() { errno = EPERM; return -1; }

    /// <summary><c>execvp(file, argv)</c> — no .NET process-image replacement;
    /// fails with EPERM. (On success exec never returns; -1 is the failure path.)</summary>
    public static int execvp(byte* file, byte** argv) { errno = EPERM; return -1; }

    /// <inheritdoc cref="execvp(byte*, byte**)"/>
    public static int execv(byte* path, byte** argv) { errno = EPERM; return -1; }

    /// <summary>Schedule the explicitly opted-in owner's cooperative SIGALRM
    /// timer, returning remaining seconds. Unbound use fails with ENOTSUP.</summary>
    public static uint alarm(uint seconds) => GuestAlarm(seconds);

    /// <summary><c>_exit(status)</c> — immediate termination, no handlers/flush
    /// (POSIX). Same backing as <see cref="_Exit"/>.</summary>
    [global::System.Diagnostics.CodeAnalysis.DoesNotReturn]
    public static void _exit(int status) => TerminateRuntime(RuntimeTerminationKind.ImmediateExit, status);

    // ---- <sys/wait.h> ------------------------------------------------------

    /// <summary><c>wait(status)</c> — dotcc has no children to reap; -1
    /// (ECHILD in spirit; dotcc carries EPERM as the closest "can't").</summary>
    public static int wait(int* status) { errno = EPERM; return -1; }

    /// <inheritdoc cref="wait(int*)"/>
    public static int waitpid(int pid, int* status, int options) { errno = EPERM; return -1; }

    // ---- <signal.h> --------------------------------------------------------

    /// <summary><c>kill(pid, sig)</c> — send signal <paramref name="sig"/> to
    /// process <paramref name="pid"/>. POSIX <c>kill(2)</c> is exact: the
    /// <c>sig==0</c> existence/permission probe, real delivery, and the
    /// ESRCH/EPERM/EINVAL <c>errno</c> are all the kernel's. Windows has no
    /// signals, so we model the two portable idioms — <c>sig==0</c> becomes an
    /// <c>OpenProcess</c> existence probe, and the terminating signals (SIGKILL 9
    /// / SIGTERM 15 / SIGINT 2) route through <c>TerminateProcess</c>. Any other
    /// signal has no Windows delivery mechanism (EINVAL), as does a
    /// <paramref name="pid"/> &lt;= 0 (POSIX process-group / broadcast target,
    /// unmodeled here).</summary>
    public static int kill(int pid, int sig)
    {
        if (RuntimeContext.Current?.GuestSignals != null)
        {
            // An embedded backend must never target the containing CLR process
            // or another backend owner through an OS process signal.
            if (pid != getpid()) { errno = EPERM; return -1; }
            return sig == 0 ? 0 : QueueGuestSignal(sig);
        }
        if (OperatingSystem.IsWindows()) { return WinKill(pid, sig); }
        var rc = PosixKill(pid, sig);
        // Surface the raw OS errno (our constants are the glibc asm-generic values).
        if (rc != 0) { errno = Marshal.GetLastPInvokeError(); }
        return rc;
    }

    [DllImport("libc", EntryPoint = "kill", SetLastError = true)]
    private static extern int PosixKill(int pid, int sig);

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern IntPtr OpenProcess(uint dwDesiredAccess, int bInheritHandle, uint dwProcessId);

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern int TerminateProcess(IntPtr hProcess, uint uExitCode);

    /// <summary>Windows <c>kill</c>: no signals, so <c>sig 0</c> is an OpenProcess
    /// existence/permission probe and the terminating signals route through
    /// TerminateProcess. <c>errno</c> mirrors POSIX <c>kill(2)</c>: ESRCH for a
    /// missing process, EPERM when it exists but the open is access-denied.</summary>
    private static int WinKill(int pid, int sig)
    {
        const uint PROCESS_TERMINATE = 0x0001;
        const uint PROCESS_QUERY_LIMITED_INFORMATION = 0x1000;
        const int ERROR_ACCESS_DENIED = 5;

        // POSIX pid <= 0 targets process groups / every process — not modeled here.
        if (pid <= 0) { errno = EINVAL; return -1; }

        if (sig == 0)
        {
            // Existence/permission probe only — no signal is sent.
            var h = OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, 0, (uint)pid);
            if (h != IntPtr.Zero) { CloseHandle(h); return 0; }
            errno = Marshal.GetLastPInvokeError() == ERROR_ACCESS_DENIED ? EPERM : ESRCH;
            return -1;
        }

        // SIGKILL (9) / SIGTERM (15) / SIGINT (2): the deliverable "terminate" signals.
        if (sig == 9 || sig == 15 || sig == 2)
        {
            var h = OpenProcess(PROCESS_TERMINATE, 0, (uint)pid);
            if (h == IntPtr.Zero)
            {
                errno = Marshal.GetLastPInvokeError() == ERROR_ACCESS_DENIED ? EPERM : ESRCH;
                return -1;
            }
            try
            {
                // 128 + signo is the conventional "killed by signal" exit code.
                if (TerminateProcess(h, (uint)(128 + sig)) != 0) { return 0; }
                errno = EPERM;
                return -1;
            }
            finally { CloseHandle(h); }
        }

        // Any other signal has no Windows delivery mechanism.
        errno = EINVAL;
        return -1;
    }

    /// <summary><c>raise(sig)</c> — deliver a registered SIGINT handler on this
    /// thread before returning, without also sending an OS signal. Default and
    /// other OS dispositions use host raise. SIGABRT retains the runtime's
    /// abnormal-termination contract.</summary>
    public static int raise(int sig)
    {
        if (RuntimeContext.Current?.GuestSignals != null) return QueueGuestSignal(sig);
        if (sig == 2)
        {
            while (true)
            {
                if (DeliverSigint()) return 0;
                lock (signalGate)
                {
                    // A concurrent signal() may have installed a handler since
                    // the delivery snapshot. Retry outside the callback gate.
                    if (sigintRegistration != null) continue;
                    return RaiseDefaultSigint();
                }
            }
        }
        if (sig == 6) { abort(); }   // SIGABRT — abnormal termination, never returns
        return RaiseHostSignal(sig);
    }

    // This is the HOST glibc Linux x64 ABI, not dotcc's struct sigaction.
    // Native sizeof/offsetof and blocked-signal action/mask roundtrips exercise
    // every field; other Unix ABIs must not use this layout.
    [StructLayout(LayoutKind.Explicit, Size = 152)]
    internal struct LinuxSignalAction
    {
        [FieldOffset(0)] public nint Handler;
        [FieldOffset(8)] public fixed ulong Mask[16];
        [FieldOffset(136)] public int Flags;
        [FieldOffset(144)] public nint Restorer;
    }

    [DllImport("libc", EntryPoint = "sigaction", SetLastError = true)]
    private static extern int HostSignalAction(int sig, LinuxSignalAction* action, LinuxSignalAction* previous);

    // Called with signalGate held and no installed C disposition. An explicit
    // process-wide C SIG_DFL request is terminal; CLR's asynchronous console
    // trampoline is not that disposition. Select the actual kernel default.
    // If blocked, raise returns with a pending signal: restore the exact CLR
    // action so subsequent registration/unblocking still uses its real backend.
    private static int RaiseDefaultSigint()
    {
        if (OperatingSystem.IsWindows()) return kill(getpid(), 2);
