        var n = (int)Math.Min(len, int.MaxValue);
        try { return sock.SendTo(new ReadOnlySpan<byte>(buf, n), ToSocketFlags(flags), ep); }
        catch (SocketException ex) { errno = SocketErrno(ex.SocketErrorCode); return -1; }
    }

    /// <summary><c>recvfrom(fd, buf, len, flags, src, srclen)</c> — datagram
    /// receive; fills <paramref name="src"/> with the sender when non-null.</summary>
    public static long recvfrom(int fd, void* buf, ulong len, int flags, void* src, uint* srclen)
    {
        var s = SlotByFd(fd);
        if (s == null) { errno = EBADF; return -1; }
        if (src == null) { return SocketRecvInto(s, buf, len, flags); }
        if (s.Socket is not { } sock) { errno = ENOTSOCK; return -1; }
        var n = (int)Math.Min(len, int.MaxValue);
        EndPoint remote = sock.AddressFamily == AddressFamily.InterNetworkV6
            ? new IPEndPoint(IPAddress.IPv6Any, 0) : new IPEndPoint(IPAddress.Any, 0);
        try
        {
            var got = sock.ReceiveFrom(new Span<byte>(buf, n), ToSocketFlags(flags), ref remote);
            if (srclen != null) WriteSockaddr(remote, src, srclen);
            return got;
        }
        catch (SocketException ex) { errno = SocketErrno(ex.SocketErrorCode); return -1; }
    }

    /// <summary><c>shutdown(fd, how)</c> — disable receive (SHUT_RD=0), send
    /// (SHUT_WR=1), or both (SHUT_RDWR=2) on a socket; ENOTSOCK for a non-socket fd
    /// (exactly what a real libc returns).</summary>
    public static int shutdown(int fd, int how)
    {
        if (SockByFd(fd, out var err) is not { } sock) { errno = err; return -1; }
        var h = how switch
        {
            0 => SocketShutdown.Receive,
            1 => SocketShutdown.Send,
            _ => SocketShutdown.Both,
        };
        try { sock.Shutdown(h); return 0; }
        catch (SocketException ex) { errno = SocketErrno(ex.SocketErrorCode); return -1; }
    }

    /// <summary><c>setsockopt(fd, level, optname, optval, optlen)</c> — the common
    /// SOL_SOCKET options + TCP_NODELAY. SO_RCVTIMEO/SO_SNDTIMEO take a
    /// <c>struct timeval</c>; SO_LINGER takes two ints, and other options one int. ENOPROTOOPT-style
    /// unknown options fail with EINVAL.</summary>
    public static int setsockopt(int fd, int level, int optname, void* optval, uint optlen)
    {
        if (SockByFd(fd, out var err) is not { } sock) { errno = err; return -1; }
        var ival = (optval != null && optlen >= 4) ? *(int*)optval : 0;
        try
        {
            if (level == SOL_SOCKET)
            {
                switch (optname)
                {
                    case SO_REUSEADDR:
                    case SO_REUSEPORT:
                        if (optlen < sizeof(int)) { errno = EINVAL; return -1; }
                        if (optval == null) { errno = EFAULT; return -1; }
                        if (OperatingSystem.IsLinux())
                        {
                            // The BCL ReuseAddress mapping also enables native
                            // SO_REUSEPORT on Unix. Preserve independent Linux
                            // flags so reuseaddr cannot share an active listener.
                            sock.SetRawSocketOption(SOL_SOCKET, optname, new ReadOnlySpan<byte>(optval, sizeof(int)));
                        }
                        else if (optname == SO_REUSEADDR)
                            sock.SetSocketOption(SocketOptionLevel.Socket, SocketOptionName.ReuseAddress, ival);
                        else { errno = ENOTSUP; return -1; }
                        break;
                    case SO_LINGER:
                        if (optlen < 8) { errno = EINVAL; return -1; }
                        if (optval == null) { errno = EFAULT; return -1; }
                        var seconds = Unsafe.ReadUnaligned<int>((byte*)optval + 4);
                        // BCL LingerTime is unsigned 16-bit on supported hosts.
                        if ((uint)seconds > ushort.MaxValue) { errno = EINVAL; return -1; }
                        sock.LingerState = new LingerOption(Unsafe.ReadUnaligned<int>((byte*)optval) != 0, seconds);
                        break;
                    case SO_KEEPALIVE: sock.SetSocketOption(SocketOptionLevel.Socket, SocketOptionName.KeepAlive, ival); break;
                    case SO_BROADCAST: sock.SetSocketOption(SocketOptionLevel.Socket, SocketOptionName.Broadcast, ival); break;
                    case SO_RCVBUF: sock.ReceiveBufferSize = ival; break;
                    case SO_SNDBUF: sock.SendBufferSize = ival; break;
                    case SO_RCVTIMEO: sock.ReceiveTimeout = TimevalToMs(optval, optlen); break;
                    case SO_SNDTIMEO: sock.SendTimeout = TimevalToMs(optval, optlen); break;
                    default: errno = EINVAL; return -1;
                }
            }
            else if (level == IPPROTO_TCP && optname == TCP_NODELAY) { sock.NoDelay = ival != 0; }
            else { errno = EINVAL; return -1; }
            return 0;
        }
        catch (SocketException ex) { errno = SocketErrno(ex.SocketErrorCode); return -1; }
    }

    /// <summary><c>getsockopt(fd, level, optname, optval, optlen)</c> — reads back
    /// the int-valued options plus the pending SO_ERROR (cleared on read) and SO_TYPE.</summary>
    public static int getsockopt(int fd, int level, int optname, void* optval, uint* optlen)
    {
        if (SockByFd(fd, out var err) is not { } sock) { errno = err; return -1; }
        if (optlen == null) { errno = EINVAL; return -1; }
        if (level == SOL_SOCKET && (optname == SO_REUSEADDR || optname == SO_REUSEPORT))
        {
            if (optname == SO_REUSEPORT && !OperatingSystem.IsLinux()) { errno = ENOTSUP; return -1; }
            if (OperatingSystem.IsLinux())
            {
                var count = (int)Math.Min(*optlen, (uint)sizeof(int));
                if (count != 0 && optval == null) { errno = EFAULT; return -1; }
                try
                {
                    *optlen = (uint)sock.GetRawSocketOption(SOL_SOCKET, optname, new Span<byte>(optval, count));
                    return 0;
                }
                catch (SocketException ex) { errno = SocketErrno(ex.SocketErrorCode); return -1; }
            }
        }
        if (level == SOL_SOCKET && optname == SO_LINGER)
        {
            if (*optlen != 0 && optval == null) { errno = EFAULT; return -1; }
            try
            {
                var linger = sock.LingerState!;
                var values = stackalloc int[2] { linger.Enabled ? 1 : 0, linger.LingerTime };
                var count = (int)Math.Min(*optlen, 8u);
                new ReadOnlySpan<byte>(values, count).CopyTo(new Span<byte>(optval, count));
                *optlen = (uint)count; // getsockopt reports bytes copied, including truncation
                return 0;
            }
            catch (SocketException ex) { errno = SocketErrno(ex.SocketErrorCode); return -1; }
        }
        if (optval == null || *optlen < 4) { errno = EINVAL; return -1; }
        try
        {
            int result;
            if (level == SOL_SOCKET)
            {
                result = optname switch
                {
                    SO_ERROR => ReadSocketError(SlotByFd(fd)!),
                    SO_TYPE => sock.SocketType == SocketType.Dgram ? SOCK_DGRAM : SOCK_STREAM,
                    SO_REUSEADDR => (int)sock.GetSocketOption(SocketOptionLevel.Socket, SocketOptionName.ReuseAddress)!,
                    SO_KEEPALIVE => (int)sock.GetSocketOption(SocketOptionLevel.Socket, SocketOptionName.KeepAlive)!,
                    SO_RCVBUF => sock.ReceiveBufferSize,
                    SO_SNDBUF => sock.SendBufferSize,
                    _ => -1,
                };
            }
            else if (level == IPPROTO_TCP && optname == TCP_NODELAY) { result = sock.NoDelay ? 1 : 0; }
            else { result = -1; }
            if (result < 0) { errno = EINVAL; return -1; }
            *(int*)optval = result;
            *optlen = 4;
            return 0;
        }
        catch (SocketException ex) { errno = SocketErrno(ex.SocketErrorCode); return -1; }
    }

    /// <summary><c>getsockname(fd, addr, addrlen)</c> — the socket's own local
    /// address (the bound endpoint; how a server on an ephemeral <c>:0</c> port
    /// learns the port the OS assigned).</summary>
    public static int getsockname(int fd, void* addr, uint* addrlen)
    {
        if (SockByFd(fd, out var err) is not { } sock) { errno = err; return -1; }
        return WriteSockaddr(sock.LocalEndPoint, addr, addrlen);
    }

    /// <summary><c>getpeername(fd, addr, addrlen)</c> — the connected peer's
    /// address.</summary>
    public static int getpeername(int fd, void* addr, uint* addrlen)
    {
        if (SockByFd(fd, out var err) is not { } sock) { errno = err; return -1; }
        return WriteSockaddr(sock.RemoteEndPoint, addr, addrlen);
    }

    /// <summary>Write a .NET endpoint into a C <c>struct sockaddr</c>, dispatching
    /// on its concrete type: <see cref="IPEndPoint"/> → <c>sockaddr_in</c>,
    /// <see cref="UnixDomainSocketEndPoint"/> → <c>sockaddr_un</c>. Truncates to the
    /// caller's buffer and reports the full length in <paramref name="addrlen"/>
    /// (POSIX getsockname/accept semantics), so a short buffer is not an error.</summary>
    private static int WriteSockaddr(EndPoint? ep, void* addr, uint* addrlen)
    {
        if (addr == null || addrlen == null) { errno = EINVAL; return -1; }
        switch (ep)
        {
            case IPEndPoint ip:
            {
                var tmp = stackalloc byte[28];
                var size = ip.AddressFamily == AddressFamily.InterNetworkV6 ? 28 : 16;
                if (size == 28) WriteSockaddrIn6(tmp, ip); else WriteSockaddrIn(tmp, ip);
                CopyTruncated(tmp, size, addr, addrlen);
                return 0;
            }
            case UnixDomainSocketEndPoint ud:
            {
                var path = Encoding.UTF8.GetBytes(ud.ToString() ?? "");
                var tmp = stackalloc byte[128];
                Unsafe.WriteUnaligned(tmp, (ushort)AF_UNIX);        // sun_family (host order)
                var plen = Math.Min(path.Length, 125);              // family(2)+path+NUL ≤ 128
                for (var i = 0; i < plen; i++) { tmp[2 + i] = path[i]; }
                tmp[2 + plen] = 0;                                  // NUL-terminate sun_path
                CopyTruncated(tmp, 2 + plen + 1, addr, addrlen);
                return 0;
            }
            default:
                errno = ENOTCONN;
                return -1;
        }
    }

    /// <summary>Copy <paramref name="srclen"/> bytes into the caller's buffer,
    /// truncating to <c>*dstlen</c>, then set <c>*dstlen</c> to the FULL length
    /// (POSIX: the stored address is truncated but the real size is reported).</summary>
    private static void CopyTruncated(byte* src, int srclen, void* dst, uint* dstlen)
    {
        var copy = (int)Math.Min((uint)srclen, *dstlen);
        new ReadOnlySpan<byte>(src, copy).CopyTo(new Span<byte>(dst, copy));
        *dstlen = (uint)srclen;
    }

    // ---- <arpa/inet.h> byte-order + address conversion ---------------------

    /// <summary><c>htons</c> — host-to-network short (endianness-correct on any host).</summary>
    public static ushort htons(ushort x) => (ushort)IPAddress.HostToNetworkOrder((short)x);

    /// <summary><c>ntohs</c> — network-to-host short.</summary>
    public static ushort ntohs(ushort x) => (ushort)IPAddress.NetworkToHostOrder((short)x);

    /// <summary><c>htonl</c> — host-to-network long (32-bit).</summary>
    public static uint htonl(uint x) => (uint)IPAddress.HostToNetworkOrder((int)x);

    /// <summary><c>ntohl</c> — network-to-host long (32-bit).</summary>
    public static uint ntohl(uint x) => (uint)IPAddress.NetworkToHostOrder((int)x);

    /// <summary><c>inet_addr(cp)</c> — dotted-quad IPv4 string to a network-order
    /// <c>in_addr_t</c>, or INADDR_NONE (<c>0xFFFFFFFF</c>) if unparseable.</summary>
    public static uint inet_addr(byte* cp)
    {
        if (cp == null) { return INADDR_NONE; }
        if (IPAddress.TryParse(Str(cp), out var ip) && ip.AddressFamily == AddressFamily.InterNetwork)
        {
            // GetAddressBytes is network order; BitConverter packs them into the
            // uint whose in-memory layout reproduces those bytes (host-agnostic).
            return BitConverter.ToUInt32(ip.GetAddressBytes());
        }
        return INADDR_NONE;
    }

    /// <summary><c>inet_pton(af, src, dst)</c> — presentation string to a packed
    /// network-order address. Returns 1 (ok), 0 (not parseable), -1 (EAFNOSUPPORT).</summary>
    public static int inet_pton(int af, byte* src, void* dst)
    {
        if (af != AF_INET && af != AF_INET6) { errno = EAFNOSUPPORT; return -1; }
        if (dst == null || src == null) { return 0; }
        // IPAddress.TryParse also accepts non-POSIX forms (IPv4 integers, hex,
        // short addresses, brackets and scope zones). Validate the presentation
        // grammar before asking the BCL to perform IPv6 expansion.
        Span<char> text = stackalloc char[45];
        int length = 0, maximum = af == AF_INET ? 15 : 45;
        while (src[length] != 0)
        {
            if (length == maximum) return 0;
            var value = src[length];
            if (value is not (>= (byte)'0' and <= (byte)'9') && value is not (>= (byte)'a' and <= (byte)'f') &&
                value is not (>= (byte)'A' and <= (byte)'F') && value != ':' && value != '.') return 0;
            text[length++] = (char)value;
        }
        var presentation = text[..length];
        Span<byte> packed = stackalloc byte[16];
        if (af == AF_INET)
        {
            if (!TryStrictIpv4(presentation, packed[..4])) return 0;
        }
        else
        {
            var colon = presentation.LastIndexOf(':');
            if (colon < 0) return 0;
            if (presentation.Contains('.') && !TryStrictIpv4(presentation[(colon + 1)..], packed[..4])) return 0;
            if (!IPAddress.TryParse(presentation, out var ip) || ip.AddressFamily != AddressFamily.InterNetworkV6 ||
                !ip.TryWriteBytes(packed, out var written) || written != 16) return 0;
        }
        packed[..(af == AF_INET ? 4 : 16)].CopyTo(new Span<byte>(dst, af == AF_INET ? 4 : 16));
        return 1;
    }

    private static bool TryStrictIpv4(ReadOnlySpan<char> text, Span<byte> output)
    {
        var offset = 0;
        for (var part = 0; part < 4; part++)
        {
            int start = offset, value = 0;
            while (offset < text.Length && text[offset] is >= '0' and <= '9')
            {
                value = value * 10 + text[offset++] - '0';
                if (offset - start > 3 || value > 255) return false;
            }
            if (offset == start || (offset - start > 1 && text[start] == '0')) return false;
            output[part] = (byte)value;
            if (part != 3 && (offset == text.Length || text[offset++] != '.')) return false;
        }
        return offset == text.Length;
    }

    /// <summary><c>inet_ntop(af, src, dst, size)</c> — packed network-order address
    /// to a presentation string in <paramref name="dst"/>; returns <paramref
    /// name="dst"/> or null (ENOSPC / EAFNOSUPPORT).</summary>
    public static byte* inet_ntop(int af, void* src, byte* dst, uint size)
    {
        if (af != AF_INET && af != AF_INET6) { errno = EAFNOSUPPORT; return null; }
        if (src == null || dst == null) { errno = EINVAL; return null; }
        var address = new ReadOnlySpan<byte>(src, af == AF_INET ? 4 : 16);
        var presentation = af == AF_INET ? new IPAddress(address).ToString() : FormatInet6(address);
        var text = Encoding.ASCII.GetBytes(presentation);
        if ((uint)(text.Length + 1) > size) { errno = ENOSPC; return null; }
        text.AsSpan().CopyTo(new Span<byte>(dst, text.Length));
        dst[text.Length] = 0;
        return dst;
    }

    private static string FormatInet6(ReadOnlySpan<byte> address)
    {
        // IPAddress.ToString also prints dotted tails for IPv4-translated and
        // ISATAP addresses, which glibc prints as hex. Format the standard
        // shortest hexadecimal form explicitly, with only glibc's mapped and
        // historical compatible-address exceptions. This is representation,
        // not address parsing or platform socket marshalling.
        Span<ushort> words = stackalloc ushort[8];
        int bestStart = -1, bestLength = 1;
        for (var i = 0; i < 8; i++) words[i] = (ushort)((address[i * 2] << 8) | address[i * 2 + 1]);
        for (var i = 0; i < 8;)
        {
            if (words[i] != 0) { i++; continue; }
            var start = i;
            while (i < 8 && words[i] == 0) i++;
            if (i - start > bestLength) { bestStart = start; bestLength = i - start; }
        }
        var dotted = bestStart == 0 && (bestLength == 6 || (bestLength == 5 && words[5] == 0xffff));
        var text = new StringBuilder(45);
        for (var i = 0; i < 8;)
        {
            if (i == bestStart) { text.Append("::"); i += bestLength; continue; }
            if (text.Length != 0 && text[text.Length - 1] != ':') text.Append(':');
            if (i == 6 && dotted) { text.Append(new IPAddress(address[12..]).ToString()); break; }
            text.Append(words[i++].ToString("x", global::System.Globalization.CultureInfo.InvariantCulture));
        }
        return text.ToString();
    }

    // ---- helpers -----------------------------------------------------------

    /// <summary>Read a C <c>struct sockaddr</c> into the matching .NET endpoint,
    /// dispatching on the family in its first two bytes: <c>AF_INET</c> →
    /// <c>sockaddr_in</c> → <see cref="IPEndPoint"/>; <c>AF_UNIX</c> → <c>sockaddr_un</c>
    /// (NUL-terminated pathname <c>sun_path</c>) → <see cref="UnixDomainSocketEndPoint"/>.
    /// Any other family is a loud <c>EAFNOSUPPORT</c>.</summary>
    private static bool TryReadSockaddr(void* addr, uint addrlen, out EndPoint ep, out int err)
    {
        ep = null!;
        err = 0;
        if (addr == null || addrlen < 2) { err = EINVAL; return false; }
        var fam = Unsafe.ReadUnaligned<ushort>((byte*)addr);   // sa_family is host order
        switch (fam)
        {
            case AF_INET:
                if (!TryReadSockaddrIn(addr, addrlen, out var ip, out err)) { return false; }
                ep = ip;
                return true;
            case AF_INET6:
            {
                if (addrlen < 28) { err = EINVAL; return false; }
                var p = (byte*)addr;
                // BCL IPEndPoint supports scope IDs; nonzero flowinfo has no
                // equivalent and is rejected rather than silently discarded.
                if (Unsafe.ReadUnaligned<uint>(p + 4) != 0) { err = EOPNOTSUPP; return false; }
                var v6 = new IPAddress(new ReadOnlySpan<byte>(p + 8, 16), Unsafe.ReadUnaligned<uint>(p + 24));
                ep = new IPEndPoint(v6, (p[2] << 8) | p[3]);
                return true;
            }
            case AF_UNIX:
            {
                // sockaddr_un: sun_family (2 bytes) then a NUL-terminated sun_path.
                var path = (byte*)addr + 2;
                var max = (int)addrlen - 2;
                var len = 0;
                while (len < max && path[len] != 0) { len++; }
                if (len == 0) { err = EINVAL; return false; }   // unnamed/abstract not modeled
                ep = new UnixDomainSocketEndPoint(Encoding.UTF8.GetString(path, len));
                return true;
            }
            default:
                err = EAFNOSUPPORT;
                return false;
        }
    }

    /// <summary>Read a <c>struct sockaddr_in</c> (family native; port + 4-byte
    /// address in network order; 16 bytes total) into an <see cref="IPEndPoint"/>.</summary>
    private static bool TryReadSockaddrIn(void* addr, uint addrlen, out IPEndPoint ep, out int err)
    {
        ep = null!;
        err = 0;
        if (addr == null || addrlen < 16) { err = EINVAL; return false; }
        var p = (byte*)addr;
        var fam = Unsafe.ReadUnaligned<ushort>(p);   // sin_family is host order
        if (fam != AF_INET) { err = EAFNOSUPPORT; return false; }
        var port = (p[2] << 8) | p[3];                  // sin_port: network order -> host
        var ipBytes = new ReadOnlySpan<byte>(p + 4, 4); // sin_addr: network order
        ep = new IPEndPoint(new IPAddress(ipBytes), port);
        return true;
    }

    /// <summary>Write an <see cref="IPEndPoint"/> into a 16-byte <c>sockaddr_in</c>.</summary>
    private static void WriteSockaddrIn(void* addr, IPEndPoint ep)
    {
        var p = (byte*)addr;
        Unsafe.WriteUnaligned(p, (ushort)AF_INET);      // sin_family (host order)
        p[2] = (byte)(ep.Port >> 8);                    // sin_port (network order)
        p[3] = (byte)ep.Port;
        var b = ep.Address.GetAddressBytes();           // 4 bytes, network order
        p[4] = b[0]; p[5] = b[1]; p[6] = b[2]; p[7] = b[3];
        for (var i = 8; i < 16; i++) { p[i] = 0; }      // sin_zero
    }

    private static void WriteSockaddrIn6(void* addr, IPEndPoint ep)
    {
        var p = (byte*)addr;
        new Span<byte>(p, 28).Clear();
        Unsafe.WriteUnaligned(p, (ushort)AF_INET6);
        p[2] = (byte)(ep.Port >> 8); p[3] = (byte)ep.Port;
        ep.Address.TryWriteBytes(new Span<byte>(p + 8, 16), out _);
        Unsafe.WriteUnaligned(p + 24, (uint)ep.Address.ScopeId);
    }

    private static int ReadSocketError(FileSlot slot)
    {
        var pending = slot.PendingSocketError;
        slot.PendingSocketError = 0;
        if (pending != 0) return pending;
        return SocketErrno((SocketError)(int)slot.Socket!.GetSocketOption(SocketOptionLevel.Socket, SocketOptionName.Error)!);
    }

    /// <summary><c>struct timeval*</c> (LP64: 8-byte tv_sec + 8-byte tv_usec) to
    /// milliseconds for a socket timeout. 0 (= no timeout / infinite) passes
    /// through, matching .NET's 0-means-infinite convention.</summary>
    private static int TimevalToMs(void* tv, uint len)
    {
        if (tv == null || len < 16) { return 0; }
        var sec = *(long*)tv;
        var usec = *(long*)((byte*)tv + 8);
        var ms = sec * 1000 + usec / 1000;
        return ms is <= 0 or > int.MaxValue ? 0 : (int)ms;
    }

    /// <summary>Map the C <c>MSG_*</c> recv/send flags we honour onto
    /// <see cref="SocketFlags"/> (others are ignored).</summary>
    private static SocketFlags ToSocketFlags(int flags)
    {
        var f = SocketFlags.None;
        if ((flags & MSG_OOB) != 0) { f |= SocketFlags.OutOfBand; }
        if ((flags & MSG_PEEK) != 0) { f |= SocketFlags.Peek; }
        return f;
    }

    /// <summary>Map a .NET <see cref="SocketError"/> onto the matching POSIX
    /// <c>errno</c>, so cross-platform C comparing errno behaves the same here as
    /// on a real libc.</summary>
    private static int SocketErrno(SocketError e) => e switch
    {
        SocketError.Success => 0,
        SocketError.ConnectionRefused => ECONNREFUSED,
        SocketError.AddressAlreadyInUse => EADDRINUSE,
        SocketError.AddressNotAvailable => EADDRNOTAVAIL,
        SocketError.AddressFamilyNotSupported => EAFNOSUPPORT,
        SocketError.ConnectionReset => ECONNRESET,
        SocketError.ConnectionAborted => ECONNABORTED,
        SocketError.IsConnected => EISCONN,
        SocketError.NotConnected => ENOTCONN,
        SocketError.TimedOut => ETIMEDOUT,
        SocketError.NetworkUnreachable => ENETUNREACH,
        SocketError.HostUnreachable => EHOSTUNREACH,
        SocketError.WouldBlock => EAGAIN,
        SocketError.InProgress => EINPROGRESS,
        SocketError.AlreadyInProgress => 114, // EALREADY
        SocketError.MessageSize => EMSGSIZE,
        SocketError.OperationNotSupported => EOPNOTSUPP,
        SocketError.ProtocolNotSupported => EPROTONOSUPPORT,
        SocketError.NotSocket => ENOTSOCK,
        SocketError.NoBufferSpaceAvailable => ENOBUFS,
        SocketError.AccessDenied => EACCES,
        SocketError.Fault => EFAULT,
        SocketError.Interrupted => EINTR,
        SocketError.Shutdown => EPIPE,
        _ => EIO,
    };
}


#nullable restore
// ---- SocketPairLib.cs ----
#nullable enable


public static unsafe partial class Libc
{
    /// <summary>Create real unnamed Linux Unix-domain peers, then transfer their
    /// handles into the ordinary BCL-backed virtual descriptor table. Other
    /// platforms report ENOTSUP; no pathname/TCP substitute is used.</summary>
    public static int socketpair(int domain, int type, int protocol, int* descriptors)
    {
        if (descriptors == null) { errno = EFAULT; return -1; }
        if (!OperatingSystem.IsLinux()) { errno = ENOTSUP; return -1; }
        var native = stackalloc int[2];
        if (LinuxSocketPair(domain, type, protocol, native) != 0)
        { errno = Marshal.GetLastPInvokeError(); return -1; }
        int firstRaw = native[0], secondRaw = native[1], firstFd = -1;
        SafeSocketHandle? firstHandle = null, secondHandle = null;
        Socket? first = null, second = null;
        try
        {
            firstHandle = new SafeSocketHandle((nint)firstRaw, ownsHandle: true); firstRaw = -1;
            secondHandle = new SafeSocketHandle((nint)secondRaw, ownsHandle: true); secondRaw = -1;
            first = new Socket(firstHandle);
            second = new Socket(secondHandle);
            first.Blocking = second.Blocking = (type & SOCK_NONBLOCK) == 0;
            var flags = (type & SOCK_CLOEXEC) == 0 ? 0 : 1;
            firstFd = RegisterSocketSlot(first, flags);
            var secondFd = RegisterSocketSlot(second, flags);
            descriptors[0] = firstFd; descriptors[1] = secondFd;
            first = second = null;
            firstHandle = secondHandle = null;
            return 0;
        }
        catch (Exception error)
        {
            if (firstFd >= 0) close(firstFd);
            errno = error is SocketException socketError ? SocketErrno(socketError.SocketErrorCode)
                : error is OutOfMemoryException ? ENOMEM : EINVAL;
            return -1;
        }
        finally
        {
            first?.Dispose(); second?.Dispose(); firstHandle?.Dispose(); secondHandle?.Dispose();
            if (firstRaw >= 0) LinuxPairClose(firstRaw);
            if (secondRaw >= 0) LinuxPairClose(secondRaw);
        }
    }

    [DllImport("libc", EntryPoint = "socketpair", SetLastError = true)]
    private static extern int LinuxSocketPair(int domain, int type, int protocol, int* descriptors);
    [DllImport("libc", EntryPoint = "close")]
    private static extern int LinuxPairClose(int descriptor);
}


