        if (command == null) { return 1; }
        var cmd = Encoding.UTF8.GetString(command, strlen(command));
        var psi = new global::System.Diagnostics.ProcessStartInfo { UseShellExecute = false, WorkingDirectory = CurrentWorkingDirectory };
        if (OperatingSystem.IsWindows())
        {
            // Mirror the MSVC CRT: ComSpec (cmd.exe) with /c, the whole string
            // handed to cmd verbatim so cmd does the parsing (system's contract).
            psi.FileName = Environment.GetEnvironmentVariable("ComSpec") ?? "cmd.exe";
            psi.Arguments = "/c " + cmd;
        }
        else
        {
            // POSIX: /bin/sh -c "<command>" — ArgumentList keeps the command a
            // single argv entry so the shell, not .NET, splits it.
            psi.FileName = "/bin/sh";
            psi.ArgumentList.Add("-c");
            psi.ArgumentList.Add(cmd);
        }
        try
        {
            using var proc = global::System.Diagnostics.Process.Start(psi);
            if (proc == null) { return -1; }
            proc.WaitForExit();
            return proc.ExitCode;
        }
        catch
        {
            return -1; // couldn't launch the interpreter
        }
    }

    // ---------------------------------------------------------------------
    // Generic sort / search (function-pointer comparator)
    // ---------------------------------------------------------------------

    /// <summary>
    /// <c>qsort(base, n, size, cmp)</c> — sort <paramref name="n"/> elements of
    /// <paramref name="size"/> bytes in place using the comparator
    /// <paramref name="cmp"/> (returns &lt;0 / 0 / &gt;0). Implemented as an
    /// in-place insertion sort (stable, O(n²)) — correct for the contract; the
    /// element-swap temp comes from a single scratch allocation.
    /// </summary>
    public static void qsort(void* @base, int n, int size, delegate*<void*, void*, int> cmp)
    {
        if (n < 2 || size <= 0) { return; }
        var b = (byte*)@base;
        var tmp = (byte*)NativeMemory.Alloc((nuint)size);
        for (var i = 1; i < n; i++)
        {
            Buffer.MemoryCopy(b + (long)i * size, tmp, size, size);
            var j = i - 1;
            while (j >= 0 && cmp(b + (long)j * size, tmp) > 0)
            {
                Buffer.MemoryCopy(b + (long)j * size, b + (long)(j + 1) * size, size, size);
                j--;
            }
            Buffer.MemoryCopy(tmp, b + (long)(j + 1) * size, size, size);
        }
        NativeMemory.Free(tmp);
    }

    /// <summary>
    /// <c>bsearch(key, base, n, size, cmp)</c> — binary-search a sorted array.
    /// Returns a pointer to a matching element or <c>null</c>. The array must be
    /// sorted consistently with <paramref name="cmp"/>.
    /// </summary>
    public static void* bsearch(void* key, void* @base, int n, int size, delegate*<void*, void*, int> cmp)
    {
        var b = (byte*)@base;
        int lo = 0, hi = n - 1;
        while (lo <= hi)
        {
            var mid = lo + (hi - lo) / 2;
            var el = b + (long)mid * size;
            var c = cmp(key, el);
            if (c < 0) { hi = mid - 1; }
            else if (c > 0) { lo = mid + 1; }
            else { return el; }
        }
        return null;
    }

    /// <summary>Instance callback ABI: forwards the same explicit owner to every
    /// comparison and keeps its runtime alive until sorting finishes.</summary>
    public static void qsort<T>(T instance, void* @base, int n, int size,
        delegate*<T, void*, void*, int> cmp) where T : class, IProgramInstance
    {
        ArgumentNullException.ThrowIfNull(instance);
        if (n < 2 || size <= 0) return;
        var context = instance.__DotCcRuntime;
        context.Retain();
        byte* temporary = null;
        try
        {
            var bytes = (byte*)@base;
            temporary = (byte*)NativeMemory.Alloc((nuint)size);
            for (var i = 1; i < n; ++i)
            {
                Buffer.MemoryCopy(bytes + (long)i * size, temporary, size, size);
                var j = i - 1;
                while (j >= 0 && cmp(instance, bytes + (long)j * size, temporary) > 0)
                {
                    Buffer.MemoryCopy(bytes + (long)j * size, bytes + (long)(j + 1) * size, size, size);
                    --j;
                }
                Buffer.MemoryCopy(temporary, bytes + (long)(j + 1) * size, size, size);
            }
        }
        finally { NativeMemory.Free(temporary); context.Release(); }
    }

    /// <summary>Instance callback ABI for binary search. Comparator adapters bind
    /// the supplied owner; the surrounding ambient context is not the identity.</summary>
    public static void* bsearch<T>(T instance, void* key, void* @base, int n, int size,
        delegate*<T, void*, void*, int> cmp) where T : class, IProgramInstance
    {
        ArgumentNullException.ThrowIfNull(instance);
        var context = instance.__DotCcRuntime;
        context.Retain();
        try
        {
            var bytes = (byte*)@base;
            int lo = 0, hi = n - 1;
            while (lo <= hi)
            {
                var mid = lo + (hi - lo) / 2;
                var element = bytes + (long)mid * size;
                var order = cmp(instance, key, element);
                if (order < 0) hi = mid - 1;
                else if (order > 0) lo = mid + 1;
                else return element;
            }
            return null;
        }
        finally { context.Release(); }
    }
}


