{
    /// <summary>POSIX bounded byte-string length. Never reads beyond the bound;
    /// a short terminated string also accepts bounds larger than Int32.MaxValue.</summary>
    public static ulong strnlen(byte* value, ulong maximum)
    {
        if (maximum != 0 && value == null) throw new ArgumentNullException(nameof(value));
        ulong length = 0;
        while (length < maximum && value[length] != 0) length++;
        return length;
    }

    // ---------------------------------------------------------------------
    // Comparison / copy — bounded variants
    // ---------------------------------------------------------------------

    /// <summary>
    /// <c>strncmp(a, b, n)</c> — lexicographic compare of at most
    /// <paramref name="n"/> bytes. Stops early at a mismatch or a shared NUL.
    /// Takes <c>nuint</c> (C size_t) per the C standard. The <c>ulong</c>
    /// overload is for callers that have dotcc's <c>size_t</c> (= ulong).
    /// </summary>
    public static int strncmp(byte* a, byte* b, nuint n) => strncmp(a, b, (ulong)n);
    public static int strncmp(byte* a, byte* b, ulong n)
    {
        if (n != 0 && (a == null || b == null)) throw new ArgumentNullException(a == null ? nameof(a) : nameof(b));
        // A huge bound is valid for short terminated strings: do not validate a
        // fictitious n-byte allocation or narrow n before the early NUL check.
        while (n-- != 0)
        {
            if (*a != *b) return *a - *b;
            if (*a == 0) return 0;
            a++; b++;
        }
        return 0;
    }

    /// <summary>
    /// <c>strncpy(dst, src, n)</c> — copy up to <paramref name="n"/> bytes from
    /// <paramref name="src"/>. If <paramref name="src"/> is shorter, the
    /// remainder of <paramref name="dst"/> is NUL-padded to <paramref name="n"/>;
    /// if it is <paramref name="n"/> or longer, <em>no</em> terminating NUL is
    /// written (the classic C99 footgun, faithfully reproduced). Returns
    /// <paramref name="dst"/>.
    /// </summary>
    public static byte* strncpy(byte* dst, byte* src, int n) => strncpy(dst, src, checked((ulong)n));
    public static byte* strncpy(byte* dst, byte* src, ulong n)
    {
        var count = ValidateMemoryRange(dst, n);
        if (count != 0 && src == null) throw new ArgumentNullException(nameof(src));
        nuint i = 0;
        for (; i < count && src[i] != 0; i++) dst[i] = src[i];
        if (i < count) memset(dst + i, 0, (ulong)(count - i));
        return dst;
    }

    // ---------------------------------------------------------------------
    // Concatenation
    // ---------------------------------------------------------------------

    /// <summary>
    /// <c>strcat(dst, src)</c> — append NUL-terminated <paramref name="src"/> to
    /// the end of NUL-terminated <paramref name="dst"/>, re-terminating. Returns
    /// <paramref name="dst"/>.
    /// </summary>
    public static byte* strcat(byte* dst, byte* src)
    {
        var p = dst;
        while (*p != 0) { p++; }
        while ((*p++ = *src++) != 0) { }
        return dst;
    }

    /// <summary>
    /// <c>strncat(dst, src, n)</c> — append at most <paramref name="n"/> bytes of
    /// <paramref name="src"/> to <paramref name="dst"/>, then always write a
    /// terminating NUL. Returns <paramref name="dst"/>.
    /// </summary>
