    }

    /// <summary>
    /// <c>strrchr(s, c)</c> — last occurrence of <c>(byte)<paramref name="c"/></c>
    /// in <paramref name="s"/>, or <c>null</c>. <c>strrchr(s, 0)</c> finds the
    /// terminating NUL.
    /// </summary>
