    /// <summary>
    /// <c>strstr(haystack, needle)</c> — pointer to the first occurrence of the
    /// NUL-terminated <paramref name="needle"/> substring within
    /// <paramref name="haystack"/>, or <c>null</c>. An empty needle returns
