    {
        var n = 0;
        while (s[n] != 0 && InSet(accept, s[n])) { n++; }
        return n;
    }

    /// <summary>
    /// <c>strcspn(s, reject)</c> — length of the initial run of
    /// <paramref name="s"/> made up of bytes that do <em>not</em> appear in
