    /// <c>strpbrk(s, accept)</c> — pointer to the first byte of
    /// <paramref name="s"/> that appears in <paramref name="accept"/>, or
    /// <c>null</c> if none do.
    /// </summary>
    public static byte* strpbrk(byte* s, byte* accept)
