    }

    // ---------------------------------------------------------------------
    // Memory — compare / move / find
    // ---------------------------------------------------------------------

    /// <summary>
    /// <c>memcmp(a, b, n)</c> — compare the first <paramref name="n"/> bytes.
    /// Returns the signed difference of the first differing pair (as
